        passiveContent.fireEvent(primaryMouseEvent(
                passiveContent,
                MouseEvent.MOUSE_PRESSED,
                4.0,
                4.0,
                true
        ));
        passiveContent.fireEvent(primaryMouseEvent(
                passiveContent,
                MouseEvent.MOUSE_RELEASED,
                4.0,
                4.0,
                false
        ));
        nestedAction.fireEvent(primaryMouseEvent(
                nestedAction,
                MouseEvent.MOUSE_PRESSED,
                4.0,
                4.0,
                true
        ));
        nestedAction.fireEvent(primaryMouseEvent(
                nestedAction,
                MouseEvent.MOUSE_RELEASED,
                4.0,
                4.0,
                false
        ));
        card.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.ENTER));

