    /// Verifies that carousel skins create an internal viewport and reveal selected items.
    @Test
    void carouselCreatesMaterialSkinAndScrollsSelectedItemIntoView() {
        FxTestUtils.runOnFxThread(() -> {
            M3Carousel carousel = carousel(
                    carouselTestItem("A"),
                    carouselTestItem("B"),
                    carouselTestItem("C"),
                    carouselTestItem("D"),
                    carouselTestItem("E")
            );
            carousel.setAnimatedScroll(false);
            carousel.setPrefSize(260.0, 100.0);
            Pane root = new Pane(carousel);
            Scene scene = new Scene(root, 280.0, 120.0);
            Stage stage = new Stage();

            try {
                M3ThemeManager.install(scene, M3Theme.defaultTheme());
                stage.setScene(scene);
                stage.show();
                root.applyCss();
                carousel.resizeRelocate(0.0, 0.0, 260.0, 100.0);
                root.layout();

                assertInstanceOf(M3CarouselSkin.class, carousel.getSkin());
                carousel.clearSelection();
                carousel.executeAccessibleAction(AccessibleAction.SHOW_ITEM);

                assertFalse(carousel.isFocused());
                assertEquals(0, carousel.getSelectedIndex());
                assertTrue(carousel.getItems().get(0).isFocused());

                carousel.getItems().get(0).fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.TAB));

                assertEquals(1, carousel.getSelectedIndex());
                assertTrue(carousel.getItems().get(1).isFocused());

                carousel.getItems().get(1).fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.TAB, true));

                assertEquals(0, carousel.getSelectedIndex());
                assertTrue(carousel.getItems().get(0).isFocused());

                carousel.selectIndex(4);
                root.layout();

                ScrollPane viewport = assertInstanceOf(
                        ScrollPane.class,
                        carousel.lookup("." + M3Carousel.VIEWPORT_STYLE_CLASS)
                );
                assertTrue(viewport.getStyleClass().contains(M3ScrollPanes.STYLE_CLASS));
                assertTrue(viewport.getHvalue() > 0.5, () -> "hvalue=" + viewport.getHvalue());
                assertTrue(M3ScrollPanes.isSmoothScrollingEnabled(viewport));

                carousel.executeAccessibleAction(AccessibleAction.SHOW_ITEM);

                assertFalse(carousel.isFocused());
                assertTrue(Objects.requireNonNull(carousel.getSelectedItem(), "selected carousel item").isFocused());

                viewport.setHvalue(0.0);
                M3MotionSettings.setReducedMotionRequested(viewport, true);
                ScrollEvent event = scrollEvent(viewport, 0.0, -80.0);
                viewport.fireEvent(event);
                root.layout();

                assertTrue(event.isConsumed());
                assertTrue(viewport.getHvalue() > 0.0, () -> "hvalue=" + viewport.getHvalue()
                        + ", contentBounds=" + viewport.getContent().getLayoutBounds()
                        + ", contentPrefWidth=" + assertInstanceOf(Region.class, viewport.getContent()).prefWidth(-1.0)
                        + ", viewport=" + viewport.getViewportBounds());


                M3MotionSettings.setReducedMotionRequested(viewport, false);
            } finally {
                stage.close();
            }
        });
    }

    /// Verifies that carousel viewports keep wheel ownership inside outer smooth scroll panes.
    @Test
    void carouselViewportKeepsWheelEventsInsideOuterSmoothScrollPane() {
        FxTestUtils.assertNoM3CssTokenWarnings(() -> FxTestUtils.runOnFxThread(() -> {
            M3Carousel carousel = carousel(
                    carouselTestItem("A"),
                    carouselTestItem("B"),
                    carouselTestItem("C"),
                    carouselTestItem("D"),
                    carouselTestItem("E")
            );
            carousel.setAnimatedScroll(false);
            carousel.setPrefSize(260.0, 100.0);

            Region filler = new Region();
            filler.setPrefSize(260.0, 360.0);
            VBox content = new VBox(carousel, filler);
            ScrollPane outerScrollPane = new ScrollPane(content);
            outerScrollPane.setPrefSize(300.0, 180.0);
            M3ScrollPanes.style(outerScrollPane);
            StackPane root = new StackPane(outerScrollPane);
            Scene scene = new Scene(root, 340.0, 240.0);
            Stage stage = new Stage();
            @Nullable ScrollPane viewport = null;

            try {
                M3ThemeManager.install(scene, M3Theme.defaultTheme());
                stage.setScene(scene);
                stage.show();
                root.applyCss();
                root.layout();

                assertInstanceOf(M3CarouselSkin.class, carousel.getSkin());
                viewport = assertInstanceOf(
                        ScrollPane.class,
                        carousel.lookup("." + M3Carousel.VIEWPORT_STYLE_CLASS)
                );
                assertTrue(viewport.getStyleClass().contains(M3ScrollPanes.STYLE_CLASS));
                assertTrue(M3ScrollPanes.isSmoothScrollingEnabled(viewport));
                assertFalse(M3ScrollPanes.isEventTargetForScrollPane(outerScrollPane, viewport));
                assertFalse(M3ScrollPanes.isEventTargetForScrollPane(outerScrollPane, viewport.getContent()));
                assertTrue(M3ScrollPanes.isEventTargetForScrollPane(outerScrollPane, filler));

                carousel.selectIndex(4);
                root.layout();
                ScrollPane currentViewport = viewport;
                assertTrue(currentViewport.getHvalue() > 0.5, () -> "hvalue=" + currentViewport.getHvalue());
                M3ScrollPanes.enableSmoothScrolling(outerScrollPane);
                M3MotionSettings.setReducedMotionRequested(outerScrollPane, true);
                M3MotionSettings.setReducedMotionRequested(viewport, true);
                viewport.setHvalue(0.0);

                ScrollEvent event = scrollEvent(viewport, 0.0, -80.0);
                viewport.fireEvent(event);

                assertTrue(currentViewport.getHvalue() > 0.0, () -> "hvalue=" + currentViewport.getHvalue());
                assertEquals(0.0, outerScrollPane.getVvalue(), 0.0001);
            } finally {
                if (viewport != null) {
                    M3MotionSettings.setReducedMotionRequested(viewport, false);
                }
                M3ScrollPanes.disableSmoothScrolling(outerScrollPane);
                M3MotionSettings.setReducedMotionRequested(outerScrollPane, false);
                stage.close();
            }
        }));
    }

    /// Verifies that running carousel scroll transitions settle when animations are disabled at runtime.
    @Tier2Test
    @Test
    void carouselSettlesRunningScrollAnimationWhenAnimationsAreDisabled() throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<@Nullable M3Carousel> carouselReference = new AtomicReference<>();
        AtomicReference<@Nullable ScrollPane> viewportReference = new AtomicReference<>();

        try {
            FxTestUtils.runOnFxThreadWhen(
                    () -> carouselViewportScrollIsInProgress(viewportReference),
                    () -> describeCarouselViewportScrollState(
                            viewportReference,
                            "Carousel viewport never reached an in-progress scroll frame"
                    ),
                    () -> {
                        M3Carousel carousel = carousel(
                                carouselTestItem("A"),
                                carouselTestItem("B"),
                                carouselTestItem("C"),
                                carouselTestItem("D"),
                                carouselTestItem("E")
                        );
                        carousel.setAnimatedScroll(true);
                        carousel.setPrefSize(260.0, 100.0);
                        Pane root = new Pane(carousel);
                        Scene scene = new Scene(root, 280.0, 120.0);
                        Stage stage = new Stage();

                        M3MotionSettings.setReducedMotionRequested(carousel, false);
                        FxTestUtils.setMotionScheme(carousel, observableTestMotionScheme());
                        stageReference.set(stage);
                        carouselReference.set(carousel);

                        M3ThemeManager.install(scene, M3Theme.defaultTheme());
                        stage.setScene(scene);
                        stage.show();
                        root.applyCss();
                        carousel.resizeRelocate(0.0, 0.0, 260.0, 100.0);
                        root.layout();

                        assertInstanceOf(M3CarouselSkin.class, carousel.getSkin());
                        ScrollPane viewport = assertInstanceOf(
                                ScrollPane.class,
                                carousel.lookup("." + M3Carousel.VIEWPORT_STYLE_CLASS)
                        );
                        viewportReference.set(viewport);

                        carousel.selectIndex(4);
                        root.layout();
                    },
                    () -> {
                        M3Carousel carousel = Objects.requireNonNull(carouselReference.get(), "carousel");
                        ScrollPane viewport = Objects.requireNonNull(viewportReference.get(), "viewport");

                        assertBetween(viewport.getHvalue(), 0.0, 1.0, "carousel animated hvalue");
                        M3MotionSettings.setReducedMotionRequested(carousel, true);
                        assertEquals(1.0, viewport.getHvalue(), 0.0001);
                    }
            );
        } finally {
            closeCarouselScrollTestWindow(stageReference, carouselReference);
        }
    }


    /// Verifies that dialog pane component token properties are styleable from CSS.
    @Test
    void dialogPaneTokensAreStyleable() {
        M3DialogPane dialogPane = new M3DialogPane();
        M3Icon graphic = new M3Icon("info");
        graphic.setStyle("-fx-opacity: 0.75;");
        dialogPane.setGraphic(graphic);
        M3Button cancelAction = new M3Button("Cancel", M3ButtonVariant.TEXT);
        cancelAction.setCancelButton(true);
        M3Button okAction = new M3Button("OK", M3ButtonVariant.TEXT);
        okAction.setDefaultButton(true);
        dialogPane.getActions().setAll(cancelAction, okAction);
        dialogPane.setStyle("-m3-container-shape: 20px; -m3-content-padding: 28px; "
                + "-m3-container-min-width: 300px; -m3-container-max-width: 520px; "
                + "-m3-action-spacing: 12px; -m3-dialog-icon-size: 28px;");
        Pane root = new Pane(dialogPane);
        Scene scene = new Scene(root, 480.0, 240.0);

        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        dialogPane.resizeRelocate(0.0, 0.0, 420.0, 180.0);
        root.applyCss();
        root.layout();
        dialogPane.layout();

        assertEquals(20.0, dialogPane.getContainerShape(), 0.0001);
        assertEquals(28.0, dialogPane.getContentPadding(), 0.0001);
        assertEquals(40.0, dialogPane.getPadding().getTop(), 0.0001);
        assertEquals(40.0, dialogPane.getPadding().getRight(), 0.0001);
        assertEquals(40.0, dialogPane.getPadding().getBottom(), 0.0001);
        assertEquals(40.0, dialogPane.getPadding().getLeft(), 0.0001);
        assertEquals(300.0, dialogPane.getContainerMinWidth(), 0.0001);
        assertEquals(520.0, dialogPane.getContainerMaxWidth(), 0.0001);
        assertEquals(12.0, dialogPane.getActionSpacing(), 0.0001);
        assertEquals(28.0, dialogPane.getIconSize(), 0.0001);
        assertEquals(324.0, dialogPane.getMinWidth(), 0.0001);
        assertEquals(544.0, dialogPane.getMaxWidth(), 0.0001);
        assertEquals(28.0, graphic.getIconSize(), 0.0001);
        assertEquals(M3IconVariant.ON_SURFACE_VARIANT, graphic.getVariant());
        assertEquals("-fx-opacity: 0.75;", graphic.getStyle());
        assertEquals(M3Theme.defaultTheme().colorScheme().getColor(org.glavo.monetfx.ColorRole.SECONDARY),
                iconFill(graphic));
        HBox actionRow = assertInstanceOf(
                HBox.class,
                dialogPane.lookup("." + M3DialogPane.ACTIONS_STYLE_CLASS)
        );
        assertEquals(12.0, actionRow.getSpacing(), 0.0001);
        assertRegionRadii(dialogPane, 20.0, 20.0, 20.0, 20.0);

        dialogPane.setContainerShape(12.0);
        root.layout();
        dialogPane.layout();

        assertEquals(12.0, dialogPane.getContainerShape(), 0.0001);
        assertRegionRadii(dialogPane, 12.0, 12.0, 12.0, 12.0);
    }

