    /// Verifies that tab bars group tabs and keep a selected tab.
    @Test
    void tabBarGroupsTabsAndKeepsSelection() {
        M3Tab overview = new M3Tab("Overview");
        M3Tab details = new M3Tab("Details");
        M3TabBar tabBar = tabBar(overview, details);

        assertTrue(overview.isSelected());
        assertEquals(overview, tabBar.getSelectedTab());
        assertEquals(java.util.List.of(overview), tabBar.getSelectedTabs());
        assertEquals(0, tabBar.getSelectedIndex());

        tabBar.selectIndex(1);

        assertFalse(overview.isSelected());
        assertTrue(details.isSelected());
        assertEquals(details, tabBar.getSelectedTab());
        assertEquals(java.util.List.of(details), tabBar.getSelectedTabs());
        assertEquals(1, tabBar.getSelectedIndex());

        details.fire();

        assertTrue(details.isSelected());
        assertEquals(details, tabBar.getSelectedTab());
        assertEquals(java.util.List.of(details), tabBar.getSelectedTabs());
        assertThrows(UnsupportedOperationException.class, () -> tabBar.getSelectedTabs().add(overview));

        tabBar.selectNext();

        assertEquals(overview, tabBar.getSelectedTab());
        assertTrue(overview.isSelected());
        assertFalse(details.isSelected());

        tabBar.selectPrevious();

        assertEquals(details, tabBar.getSelectedTab());
        assertFalse(overview.isSelected());
        assertTrue(details.isSelected());

        tabBar.clearSelection();

        assertEquals(details, tabBar.getSelectedTab());
        assertEquals(java.util.List.of(details), tabBar.getSelectedTabs());

        tabBar.setAllowEmptySelection(true);
        tabBar.clearSelection();

        assertNull(tabBar.getSelectedTab());
        assertTrue(tabBar.getSelectedTabs().isEmpty());
        assertEquals(-1, tabBar.getSelectedIndex());
        assertFalse(overview.isSelected());
        assertFalse(details.isSelected());

        tabBar.setAllowEmptySelection(false);

        assertEquals(overview, tabBar.getSelectedTab());
        assertEquals(java.util.List.of(overview), tabBar.getSelectedTabs());
        assertTrue(overview.isSelected());
    }

    /// Verifies fixed and scrollable primary and secondary tab geometry, reveal behavior, and feedback.
    @Test
    void tabSkinLaysOutIndicatorAndRipple() {
        M3Tab primaryTab = new M3Tab("Overview");
        M3Tab secondaryTab = new M3Tab("Specifications");
        M3TabBar primaryBar = tabBar(primaryTab, new M3Tab("Activity"));
        M3TabBar secondaryBar = tabBar(secondaryTab, new M3Tab("Reviews"));
        secondaryBar.setVariant(M3TabBarVariant.SECONDARY);
        M3Tab firstScrollableTab = new M3Tab("Overview");
        M3Tab longScrollableTab = new M3Tab("Technical specifications");
        M3Tab lastScrollableTab = new M3Tab("Connected applications");
        M3TabBar scrollableBar = tabBar(
                firstScrollableTab,
                new M3Tab("Recent activity"),
                longScrollableTab,
                new M3Tab("Storage management"),
                lastScrollableTab
        );
        scrollableBar.setTabLayout(M3TabBarLayout.SCROLLABLE);
        VBox root = new VBox(primaryBar, secondaryBar, scrollableBar);
        Scene scene = new Scene(root, 360.0, 144.0);

        M3Theme theme = M3Theme.defaultTheme();
        M3ThemeManager.install(scene, theme);
        root.applyCss();
        root.layout();

        PseudoClass secondaryPseudoClass = PseudoClass.getPseudoClass("secondary");
        assertEquals(M3TabBarVariant.PRIMARY, primaryBar.getVariant());
        assertEquals(M3TabBarVariant.SECONDARY, secondaryBar.getVariant());
        assertFalse(primaryTab.getPseudoClassStates().contains(secondaryPseudoClass));
        assertTrue(secondaryBar.getPseudoClassStates().contains(secondaryPseudoClass));
        assertTrue(secondaryTab.getPseudoClassStates().contains(secondaryPseudoClass));
        assertEquals(
                primaryTab.getWidth(),
                assertInstanceOf(M3Tab.class, primaryBar.getTabs().get(1)).getWidth(),
                0.0001
        );
        assertEquals(
                secondaryTab.getWidth(),
                assertInstanceOf(M3Tab.class, secondaryBar.getTabs().get(1)).getWidth(),
                0.0001
        );
        assertEquals(primaryBar.getWidth() / 2.0, primaryTab.getWidth(), 0.0001);
        assertEquals(secondaryBar.getWidth() / 2.0, secondaryTab.getWidth(), 0.0001);
        assertEquals(M3TabBarLayout.FIXED, primaryBar.getTabLayout());
        assertEquals(M3TabBarLayout.SCROLLABLE, scrollableBar.getTabLayout());
        assertTrue(scrollableBar.getPseudoClassStates().contains(PseudoClass.getPseudoClass("scrollable")));
        assertEquals(52.0, firstScrollableTab.getLayoutX(), 0.75);
        assertTrue(longScrollableTab.getWidth() > firstScrollableTab.getWidth(),
                "scrollable tab widths should follow their labels");
        assertTrue(lastScrollableTab.getLayoutX() >= scrollableBar.getWidth(),
                "the overflowing final tab should begin outside the initial viewport");
        for (Node node : scrollableBar.getTabs()) {
            M3Tab tab = assertInstanceOf(M3Tab.class, node);
            Text label = assertInstanceOf(Text.class, tab.lookup(".text"));
            assertEquals(tab.getText(), label.getText(), () -> "scrollable tab labels should remain complete: text="
                    + tab.getText() + ", width=" + tab.getWidth() + ", prefWidth=" + tab.prefWidth(-1.0)
                    + ", minWidth=" + tab.minWidth(-1.0) + ", padding=" + tab.getPadding());
        }

        Region primaryIndicator = lookupRegion(primaryTab, ".m3-tab-active-indicator");
        Region secondaryIndicator = lookupRegion(secondaryTab, ".m3-tab-active-indicator");
        Text primaryText = assertInstanceOf(Text.class, primaryTab.lookup(".text"));
        double expectedPrimaryIndicatorWidth = Math.max(
                primaryTab.getActiveIndicatorMinWidth(),
                primaryText.getBoundsInParent().getWidth()
                        + primaryTab.getActiveIndicatorHorizontalInset() * 2.0
        );
        assertEquals(expectedPrimaryIndicatorWidth, primaryIndicator.getWidth(), 1.0);
        assertTrue(primaryIndicator.getWidth() < primaryTab.getWidth());
        assertEquals(3.0, primaryIndicator.getHeight(), 0.0001);
        assertEquals(3.0, primaryTab.getActiveIndicatorShape(), 0.0001);
        assertEquals(1.0, primaryIndicator.getOpacity(), 0.0001);
        assertEquals(secondaryTab.getWidth(), secondaryIndicator.getWidth(), 0.0001);
        assertEquals(2.0, secondaryIndicator.getHeight(), 0.0001);
        assertEquals(0.0, secondaryTab.getActiveIndicatorShape(), 0.0001);
        assertEquals(1.0, secondaryIndicator.getOpacity(), 0.0001);
        assertEquals(
                theme.colorScheme().getColor(org.glavo.monetfx.ColorRole.PRIMARY),
                primaryTab.getTextFill()
        );
        assertEquals(
                theme.colorScheme().getColor(org.glavo.monetfx.ColorRole.ON_SURFACE),
                secondaryTab.getTextFill()
        );

        Region primaryDivider = lookupRegion(primaryBar, "." + M3TabBar.DIVIDER_STYLE_CLASS);
        Region secondaryDivider = lookupRegion(secondaryBar, "." + M3TabBar.DIVIDER_STYLE_CLASS);
        assertEquals(1.0, primaryDivider.getHeight(), 0.0001);
        assertEquals(1.0, secondaryDivider.getHeight(), 0.0001);
        assertEquals(primaryBar.getWidth(), primaryDivider.getWidth(), 0.0001);
        assertEquals(secondaryBar.getWidth(), secondaryDivider.getWidth(), 0.0001);

        secondaryTab.fireEvent(primaryMouseEvent(MouseEvent.MOUSE_PRESSED, 40.0, 24.0, true));
        assertTrue(secondaryTab.isArmed());
        secondaryTab.fireEvent(primaryMouseEvent(MouseEvent.MOUSE_RELEASED, 40.0, 24.0, false));

        assertTrue(lookupRegion(secondaryTab, ".m3-ripple").getOpacity() > 0.0);

        secondaryBar.setVariant(M3TabBarVariant.PRIMARY);
        assertFalse(secondaryBar.getPseudoClassStates().contains(secondaryPseudoClass));
        assertFalse(secondaryTab.getPseudoClassStates().contains(secondaryPseudoClass));
        secondaryBar.setVariant(M3TabBarVariant.SECONDARY);
        assertTrue(secondaryBar.getPseudoClassStates().contains(secondaryPseudoClass));
        assertTrue(secondaryTab.getPseudoClassStates().contains(secondaryPseudoClass));

        M3MotionSettings.setReducedMotionRequested(root, true);
        scrollableBar.select(lastScrollableTab);
        root.layout();
        root.layout();
        assertTrue(lastScrollableTab.getLayoutX() + lastScrollableTab.getWidth() <= scrollableBar.getWidth() + 0.75,
                "selection should reveal the complete final tab");

        scrollableBar.select(firstScrollableTab);
        root.layout();
        root.layout();
        assertEquals(52.0, firstScrollableTab.getLayoutX(), 0.75,
                "returning to the first tab should restore the Material leading offset");
        scrollableBar.fireEvent(scrollEvent(scrollableBar, 0.0, -36.0, false, false));
        root.layout();
        assertEquals(16.0, firstScrollableTab.getLayoutX(), 0.75,
                "vertical wheel movement should browse the horizontal tab track");

        scrollableBar.setNodeOrientation(NodeOrientation.RIGHT_TO_LEFT);
        scrollableBar.select(lastScrollableTab);
        scrollableBar.select(firstScrollableTab);
        root.layout();
        root.layout();
        Bounds firstRtlBounds = firstScrollableTab.localToScene(firstScrollableTab.getBoundsInLocal());
        Bounds scrollableBarBounds = scrollableBar.localToScene(scrollableBar.getBoundsInLocal());
        assertEquals(scrollableBarBounds.getMaxX() - 52.0, firstRtlBounds.getMaxX(), 0.75,
                "RTL scrollable tabs should apply the leading offset from the right edge");
        M3MotionSettings.setReducedMotionRequested(root, false);
    }

    /// Verifies that selection component token properties are styleable from CSS.
    @Test
    void selectionTokensAreStyleable() {
        M3CheckBox checkBox = new M3CheckBox("Check");
        checkBox.setStyle("""
                -m3-touch-target-size: 44px;
                -m3-state-layer-size: 38px;
                -m3-container-size: 20px;
                -m3-selected-mark-width: 13px;
                -m3-selected-mark-height: 11px;
                -m3-indeterminate-mark-width: 14px;
                -m3-indeterminate-mark-height: 3px;
                """);

        M3RadioButton radioButton = new M3RadioButton("Radio");
        radioButton.setStyle("""
                -m3-touch-target-size: 46px;
                -m3-state-layer-size: 36px;
                -m3-container-size: 22px;
                -m3-selected-dot-size: 12px;
                """);

        M3Switch switchControl = new M3Switch("Switch");
        switchControl.setStyle("""
                -m3-touch-target-size: 50px;
                -m3-track-shape: 18px;
                -m3-track-width: 60px;
                -m3-track-height: 36px;
                -m3-state-layer-size: 44px;
                -m3-unselected-handle-size: 18px;
                -m3-with-icon-handle-size: 27px;
                -m3-selected-handle-size: 26px;
                -m3-pressed-handle-size: 30px;
                -m3-icon-size: 15px;
                """);

        applyCss(checkBox);
        applyCss(radioButton);
        applyCss(switchControl);

        assertEquals(44.0, checkBox.getTouchTargetSize(), 0.0001);
        assertEquals(38.0, checkBox.getStateLayerSize(), 0.0001);
        assertEquals(20.0, checkBox.getContainerSize(), 0.0001);
        assertEquals(13.0, checkBox.getSelectedMarkWidth(), 0.0001);
        assertEquals(11.0, checkBox.getSelectedMarkHeight(), 0.0001);
        assertEquals(14.0, checkBox.getIndeterminateMarkWidth(), 0.0001);
        assertEquals(3.0, checkBox.getIndeterminateMarkHeight(), 0.0001);
        assertEquals(44.0, checkBox.getPrefHeight(), 0.0001);
        assertEquals(46.0, radioButton.getTouchTargetSize(), 0.0001);
        assertEquals(36.0, radioButton.getStateLayerSize(), 0.0001);
        assertEquals(22.0, radioButton.getContainerSize(), 0.0001);
        assertEquals(12.0, radioButton.getSelectedDotSize(), 0.0001);
        assertEquals(46.0, radioButton.getPrefHeight(), 0.0001);
        assertEquals(50.0, switchControl.getTouchTargetSize(), 0.0001);
        assertEquals(18.0, switchControl.getTrackShape(), 0.0001);
        assertEquals(60.0, switchControl.getTrackWidth(), 0.0001);
        assertEquals(36.0, switchControl.getTrackHeight(), 0.0001);
        assertEquals(44.0, switchControl.getStateLayerSize(), 0.0001);
        assertEquals(18.0, switchControl.getUnselectedHandleSize(), 0.0001);
        assertEquals(27.0, switchControl.getWithIconHandleSize(), 0.0001);
        assertEquals(26.0, switchControl.getSelectedHandleSize(), 0.0001);
        assertEquals(30.0, switchControl.getPressedHandleSize(), 0.0001);
        assertEquals(15.0, switchControl.getIconSize(), 0.0001);
        assertEquals(50.0, switchControl.getPrefHeight(), 0.0001);

        switchControl.setStyle(switchControl.getStyle() + " -m3-state-layer-size: 54px;");
        applyCss(switchControl);
        assertEquals(54.0, switchControl.getStateLayerSize(), 0.0001);
        assertEquals(54.0, switchControl.getPrefHeight(), 0.0001);
    }

    /// Verifies that switch handle icons use the MD3 icon slot, handle size, color roles, and ownership lifecycle.
    @Test
    void switchSupportsSelectedAndUnselectedHandleIcons() {
        SVGPath selectedIcon = new SVGPath();
        selectedIcon.setContent("M 2 8 L 6 12 L 14 3 L 12 1 L 6 8 L 4 6 Z");
        selectedIcon.getStyleClass().add("application-selected-icon");
        SVGPath unselectedIcon = new SVGPath();
        unselectedIcon.setContent("M 3 3 L 13 13 M 13 3 L 3 13");
        M3Switch switchControl = new M3Switch("Notifications");
        switchControl.setSelectedIcon(selectedIcon);
        switchControl.setUnselectedIcon(unselectedIcon);
        M3MotionSettings.setReducedMotionRequested(switchControl, true);

        Pane root = new Pane(switchControl);
        Scene scene = new Scene(root, 180.0, 80.0);
        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        root.setStyle("""
                -m3-color-primary: rgb(1,2,3);
                -m3-color-surface-container-highest: rgb(10,11,12);
                -m3-color-on-surface: rgb(20,21,22);
                """);
        root.applyCss();
        switchControl.resizeRelocate(20.0, 16.0, 140.0, 48.0);
        switchControl.layout();

        Region thumb = lookupRegion(switchControl, ".thumb");
        Region iconSlot = lookupRegion(switchControl, ".m3-switch-icon-slot");
        assertSame(iconSlot, unselectedIcon.getParent());
        assertNull(selectedIcon.getParent());
        assertEquals(24.0, thumb.getWidth(), 0.0001);
        assertEquals(24.0, thumb.getHeight(), 0.0001);
        assertEquals(16.0, iconSlot.getWidth(), 0.0001);
        assertEquals(16.0, iconSlot.getHeight(), 0.0001);
        assertEquals(Color.rgb(10, 11, 12), unselectedIcon.getFill());
        assertTrue(unselectedIcon.getStyleClass().contains("m3-switch-handle-icon"));

        switchControl.setDisable(true);
        root.applyCss();
        assertEquals(Color.rgb(10, 11, 12), unselectedIcon.getFill());
        assertEquals(0.38, unselectedIcon.getOpacity(), 0.0001);

        switchControl.setDisable(false);
        switchControl.setSelected(true);
        root.applyCss();
        switchControl.layout();

        assertSame(iconSlot, selectedIcon.getParent());
        assertNull(unselectedIcon.getParent());
        assertFalse(unselectedIcon.getStyleClass().contains("m3-switch-handle-icon"));
        assertTrue(selectedIcon.getStyleClass().contains("application-selected-icon"));
        assertTrue(selectedIcon.getStyleClass().contains("m3-switch-handle-icon"));
        assertEquals(Color.rgb(1, 2, 3), selectedIcon.getFill());
        assertEquals(1.0, iconSlot.getOpacity(), 0.0001);

        switchControl.setDisable(true);
        root.applyCss();
        assertEquals(Color.rgb(20, 21, 22), selectedIcon.getFill());
        assertEquals(0.38, selectedIcon.getOpacity(), 0.0001);

        M3SwitchSkin skin = assertInstanceOf(M3SwitchSkin.class, switchControl.getSkin());
        skin.dispose();

        assertNull(selectedIcon.getParent());
        assertFalse(selectedIcon.getStyleClass().contains("m3-switch-handle-icon"));
        assertTrue(selectedIcon.getStyleClass().contains("application-selected-icon"));
    }

    /// Verifies MD3 hover, focus, pressed, and disabled color mappings for selection controls.
    @Test
    void selectionControlStateColorsFollowMaterialTokens() {
        M3CheckBox checkBox = new M3CheckBox("Check");
        M3RadioButton radioButton = new M3RadioButton("Radio");
        M3Switch switchControl = new M3Switch("Switch");
        Pane root = new Pane(checkBox, radioButton, switchControl);
        Scene scene = new Scene(root, 420.0, 80.0);
        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        root.setStyle("""
                -m3-color-primary: rgb(1,2,3);
                -m3-color-on-surface: rgb(4,5,6);
                -m3-color-on-surface-variant: rgb(7,8,9);
                -m3-color-surface-container-highest: rgb(10,11,12);
                -m3-color-error: rgb(13,14,15);
                -m3-color-on-error: rgb(16,17,18);
                -m3-color-surface: rgb(19,20,21);
                -m3-color-outline: rgb(22,23,24);
                -m3-color-on-primary: rgb(25,26,27);
                -m3-color-primary-container: rgb(28,29,30);
                """);
        root.applyCss();

        Region checkBoxContainer = lookupRegion(checkBox, ".box");
        Shape radioRing = radioRing(radioButton);
        Region checkBoxStateLayer = lookupRegion(checkBox, ".m3-state-layer");
        Region radioStateLayer = lookupRegion(radioButton, ".m3-state-layer");
        assertBorderColor(checkBoxContainer, Color.rgb(7, 8, 9));
        assertEquals(Color.rgb(7, 8, 9), radioRing.getStroke());

        checkBox.pseudoClassStateChanged(PseudoClass.getPseudoClass("hover"), true);
        radioButton.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), true);
        root.applyCss();
        assertBorderColor(checkBoxContainer, Color.rgb(4, 5, 6));
        assertEquals(Color.rgb(4, 5, 6), radioRing.getStroke());

        checkBox.arm();
        radioButton.arm();
        root.applyCss();
        assertRegionFill(checkBoxStateLayer, Color.rgb(1, 2, 3));
        assertRegionFill(radioStateLayer, Color.rgb(1, 2, 3));

        checkBox.setSelected(true);
        radioButton.setSelected(true);
        root.applyCss();
        assertRegionFill(checkBoxStateLayer, Color.rgb(4, 5, 6));
        assertRegionFill(radioStateLayer, Color.rgb(4, 5, 6));
        assertNoBorder(checkBoxContainer);

        checkBox.disarm();
        checkBox.setSelected(false);
        checkBox.setError(true);
        root.applyCss();
        assertTrue(checkBox.getPseudoClassStates().contains(PseudoClass.getPseudoClass("error")));
        assertBorderColor(checkBoxContainer, Color.rgb(13, 14, 15));
        assertRegionFill(checkBoxStateLayer, Color.rgb(13, 14, 15));

        checkBox.setSelected(true);
        root.applyCss();
        assertRegionFill(checkBoxContainer, Color.rgb(13, 14, 15));
        assertRegionFill(lookupRegion(checkBox, ".mark"), Color.rgb(16, 17, 18));
        assertNoBorder(checkBoxContainer);

        checkBox.setSelected(false);
        checkBox.setIndeterminate(true);
        root.applyCss();
        assertRegionFill(checkBoxContainer, Color.rgb(13, 14, 15));
        assertRegionFill(lookupRegion(checkBox, ".mark"), Color.rgb(16, 17, 18));
        assertNoBorder(checkBoxContainer);

        checkBox.setDisable(true);
        root.applyCss();
        assertRegionFill(checkBoxContainer, Color.rgb(4, 5, 6));
        assertEquals(0.38, checkBoxContainer.getOpacity(), 0.0001);
        assertRegionFill(lookupRegion(checkBox, ".mark"), Color.rgb(19, 20, 21));

        Region switchTrack = lookupRegion(switchControl, ".box");
        Region switchThumb = lookupRegion(switchControl, ".thumb");
        Region switchStateLayer = lookupRegion(switchControl, ".m3-state-layer");
        assertRegionFill(switchTrack, Color.rgb(10, 11, 12));
        assertBorderColor(switchTrack, Color.rgb(22, 23, 24));
        assertRegionFill(switchThumb, Color.rgb(22, 23, 24));
        assertRegionFill(switchStateLayer, Color.rgb(4, 5, 6));

        switchControl.pseudoClassStateChanged(PseudoClass.getPseudoClass("hover"), true);
        root.applyCss();
        assertRegionFill(switchTrack, Color.rgb(10, 11, 12));
        assertBorderColor(switchTrack, Color.rgb(22, 23, 24));
        assertRegionFill(switchThumb, Color.rgb(7, 8, 9));
        assertRegionFill(switchStateLayer, Color.rgb(4, 5, 6));

        switchControl.pseudoClassStateChanged(PseudoClass.getPseudoClass("hover"), false);
        switchControl.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), true);
        root.applyCss();
        assertRegionFill(switchThumb, Color.rgb(7, 8, 9));
        assertRegionFill(switchStateLayer, Color.rgb(4, 5, 6));

        switchControl.pseudoClassStateChanged(PseudoClass.getPseudoClass("focus-visible"), false);
        switchControl.arm();
        root.applyCss();
        assertRegionFill(switchThumb, Color.rgb(7, 8, 9));
        assertRegionFill(switchStateLayer, Color.rgb(4, 5, 6));

        switchControl.disarm();
        switchControl.setSelected(true);
        root.applyCss();
        assertRegionFill(switchTrack, Color.rgb(1, 2, 3));
        assertNoBorder(switchTrack);
        assertRegionFill(switchThumb, Color.rgb(25, 26, 27));
        assertRegionFill(switchStateLayer, Color.rgb(1, 2, 3));

        switchControl.pseudoClassStateChanged(PseudoClass.getPseudoClass("hover"), true);
        root.applyCss();
        assertRegionFill(switchThumb, Color.rgb(28, 29, 30));
        assertRegionFill(switchStateLayer, Color.rgb(1, 2, 3));

        switchControl.pseudoClassStateChanged(PseudoClass.getPseudoClass("hover"), false);
        switchControl.setDisable(true);
        root.applyCss();
        assertRegionFill(switchTrack, Color.rgb(4, 5, 6));
        assertEquals(0.12, switchTrack.getOpacity(), 0.0001);
        assertRegionFill(switchThumb, Color.rgb(19, 20, 21));
        assertEquals(1.0, switchThumb.getOpacity(), 0.0001);

        switchControl.setSelected(false);
        root.applyCss();
        assertRegionFill(switchTrack, Color.rgb(10, 11, 12));
        assertBorderColor(switchTrack, Color.rgb(4, 5, 6));
        assertEquals(0.12, switchTrack.getOpacity(), 0.0001);
        assertRegionFill(switchThumb, Color.rgb(4, 5, 6));
        assertEquals(0.38, switchThumb.getOpacity(), 0.0001);
    }

    /// Verifies that selection controls create Material Design 3 skins.
