        assertEquals(86.0, bottomAppBar.getPrefHeight(), 0.0001);
        assertEquals(86.0, bottomAppBar.getContainerHeight(), 0.0001);
        assertEquals(20.0, bottomAppBar.getHorizontalPadding(), 0.0001);
