                assertTrue(share.isFocused());
                bottomAppBar.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.RIGHT));
                assertTrue(create.isFocused());
                bottomAppBar.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.RIGHT));
                assertTrue(archive.isFocused());
