    /// Verifies that outlined text input layouts cut a real outline notch instead of painting a label mask.
    @Tier2Test
    @Test
    void outlinedInputLayoutSnapshotRendersNotchedOutlineWithoutLabelMask() {
        FxTestUtils.runOnFxThread(() -> {
            M3TextField textField = createTextField("M3FX", M3TextInputVariant.OUTLINED);
            textField.setPrefWidth(360.0);

            M3TextInputLayout layout = new M3TextInputLayout(textField, "Project name");
            layout.setLabelText("Outlined with text");
            layout.setLeading(visualIcon("text"));
            layout.setCharacterCounterVisible(true);
            layout.setCharacterLimit(24);
            layout.setPrefWidth(360.0);

            Color surface = Color.rgb(248, 240, 249);
            StackPane root = new StackPane(layout);
            root.setAlignment(Pos.TOP_LEFT);
            root.setStyle("-fx-background-color: rgb(248, 240, 249); -fx-padding: 20px; " + visualTestColors());
            Scene scene = new Scene(root, 430.0, 140.0);

            M3ThemeManager.install(scene, M3Theme.defaultTheme());
            root.applyCss();
            root.resize(430.0, 140.0);
            root.layout();

            assertVisualIconSlotsUseVectorGraphics(root);

            WritableImage image = snapshotImageOnFxThread(root);
            Label label = assertInstanceOf(Label.class, layout.lookup("." + M3TextInputLayout.LABEL_STYLE_CLASS));
            Path outline = assertInstanceOf(Path.class, layout.lookup("." + M3TextInputLayout.OUTLINE_STYLE_CLASS));
            Text inputText = renderedTextNode(textField, "M3FX");
            var labelBounds = label.localToScene(label.getBoundsInLocal());
            var fieldBounds = textField.localToScene(textField.getBoundsInLocal());
            var inputTextBounds = inputText.localToScene(inputText.getBoundsInLocal());
            Rectangle2D inputInkBounds = requiredRenderedTextInkBounds(image, inputText);
            double fieldCenterY = (fieldBounds.getMinY() + fieldBounds.getMaxY()) / 2.0;
            double inputTextCenterY = inputTextBounds.getCenterY();

            assertEquals(11.0, textField.getPadding().getTop(), 0.0001);
            assertEquals(fieldCenterY, inputTextCenterY, 4.0,
                    () -> "outlined input line box should stay vertically centered: field="
                            + fieldBounds + ", text=" + inputTextBounds + ", ink=" + inputInkBounds);
            assertTrue(label.getBackground() == null || label.getBackground().getFills().isEmpty());
            assertTrue(outlineNotchGap(outline) >= labelBounds.getWidth() - 1.0,
                    () -> "outline gap is narrower than the floating label: gap="
                            + outlineNotchGap(outline) + ", label=" + labelBounds);
            assertTrue(labelBounds.getMinY() < fieldBounds.getMinY(),
                    () -> "floating label should start above the outline top: field="
                            + fieldBounds + ", label=" + labelBounds);
            assertTrue(labelBounds.getMaxY() > fieldBounds.getMinY(),
                    () -> "floating label should straddle the outline top: field="
                            + fieldBounds + ", label=" + labelBounds);
            assertTrue(Math.abs(labelBounds.getCenterY() - fieldBounds.getMinY()) < 6.0,
                    () -> "floating label should be centered around the outline top: field="
                            + fieldBounds + ", label=" + labelBounds);

            Color labelPaddingPixel = averageSnapshotColor(
                    image,
                    (int) Math.floor(labelBounds.getMinX()),
                    (int) Math.floor(labelBounds.getCenterY() - 2.0),
                    (int) Math.floor(labelBounds.getMinX() + 4.0),
                    (int) Math.floor(labelBounds.getCenterY() + 3.0)
            );
            Color notchPixel = averageSnapshotColor(
                    image,
                    (int) Math.floor(labelBounds.getMinX()),
                    (int) Math.floor(fieldBounds.getMinY()),
                    (int) Math.floor(labelBounds.getMinX() + 4.0),
                    (int) Math.floor(fieldBounds.getMinY() + 3.0)
            );
            assertColorNear(labelPaddingPixel, surface, 0.09, "floating label padding area");
            assertColorNear(notchPixel, surface, 0.05, "outlined notch area");
            assertSnapshotAreaContainsContrast(
                    image,
                    (int) Math.floor(fieldBounds.getMinX() + 4.0),
                    (int) Math.floor(fieldBounds.getMinY()),
                    (int) Math.floor(labelBounds.getMinX() - 2.0),
                    (int) Math.ceil(fieldBounds.getMinY() + 3.0),
                    surface,
                    0.04,
                    "outlined text field top outline before floating label notch"
            );
            writeVisualSnapshot(image, java.nio.file.Path.of(
                    "build",
                    "reports",
                    "m3fx-visual",
                    "visual-outlined-input-notch.png"
            ));
            assertSingleLineTextInputsKeepInkAligned(root);
        });
    }

    /// Verifies that validation summaries mirror text alignment when orientation changes at runtime.
    @Test
    void validationSummaryMirrorsTextAlignmentWhenOrientationChanges() {
        FxTestUtils.runOnFxThread(() -> {
            M3TextField field = new M3TextField();
            M3TextInputLayout layout = new M3TextInputLayout(field, "Display name", "Required");
            layout.setValidator(M3TextInputValidators.required("Display name is required"));
            M3FormValidator validator = new M3FormValidator(layout);
            assertFalse(validator.validate());

            M3ValidationSummary summary = new M3ValidationSummary(validator);
            summary.setPrefWidth(360.0);
            Pane root = new Pane(summary);
            Scene scene = new Scene(root, 380.0, 120.0);
            M3ThemeManager.install(scene, M3Theme.defaultTheme());
            root.applyCss();
            summary.resize(360.0, 100.0);
            summary.layout();

            Label title = assertInstanceOf(
                    Label.class,
                    summary.lookup("." + M3ValidationSummary.TITLE_STYLE_CLASS)
            );
            Label itemLabel = assertInstanceOf(
                    Label.class,
                    summary.lookup("." + M3ValidationSummary.ITEM_LABEL_STYLE_CLASS)
            );
            Label itemError = assertInstanceOf(
                    Label.class,
                    summary.lookup("." + M3ValidationSummary.ITEM_ERROR_STYLE_CLASS)
            );
            assertEquals(Pos.CENTER_LEFT, title.getAlignment());
            assertEquals(Pos.CENTER_LEFT, itemLabel.getAlignment());
            assertEquals(Pos.CENTER_LEFT, itemError.getAlignment());
            assertEquals(TextAlignment.LEFT, title.getTextAlignment());
            assertEquals(TextAlignment.LEFT, itemLabel.getTextAlignment());
            assertEquals(TextAlignment.LEFT, itemError.getTextAlignment());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, title.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, itemLabel.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, itemError.getEffectiveNodeOrientation());

            summary.setNodeOrientation(NodeOrientation.RIGHT_TO_LEFT);
            root.applyCss();
            summary.layout();

            title = assertInstanceOf(Label.class, summary.lookup("." + M3ValidationSummary.TITLE_STYLE_CLASS));
            itemLabel = assertInstanceOf(Label.class, summary.lookup("." + M3ValidationSummary.ITEM_LABEL_STYLE_CLASS));
            itemError = assertInstanceOf(Label.class, summary.lookup("." + M3ValidationSummary.ITEM_ERROR_STYLE_CLASS));
            assertEquals(Pos.CENTER_RIGHT, title.getAlignment());
            assertEquals(Pos.CENTER_RIGHT, itemLabel.getAlignment());
            assertEquals(Pos.CENTER_RIGHT, itemError.getAlignment());
            assertEquals(TextAlignment.RIGHT, title.getTextAlignment());
            assertEquals(TextAlignment.RIGHT, itemLabel.getTextAlignment());
            assertEquals(TextAlignment.RIGHT, itemError.getTextAlignment());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, title.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, itemLabel.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, itemError.getEffectiveNodeOrientation());

            summary.setNodeOrientation(NodeOrientation.LEFT_TO_RIGHT);
            root.applyCss();
            summary.layout();

            title = assertInstanceOf(Label.class, summary.lookup("." + M3ValidationSummary.TITLE_STYLE_CLASS));
            itemLabel = assertInstanceOf(Label.class, summary.lookup("." + M3ValidationSummary.ITEM_LABEL_STYLE_CLASS));
            itemError = assertInstanceOf(Label.class, summary.lookup("." + M3ValidationSummary.ITEM_ERROR_STYLE_CLASS));
            assertEquals(Pos.CENTER_LEFT, title.getAlignment());
            assertEquals(Pos.CENTER_LEFT, itemLabel.getAlignment());
            assertEquals(Pos.CENTER_LEFT, itemError.getAlignment());
            assertEquals(TextAlignment.LEFT, title.getTextAlignment());
            assertEquals(TextAlignment.LEFT, itemLabel.getTextAlignment());
            assertEquals(TextAlignment.LEFT, itemError.getTextAlignment());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, title.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, itemLabel.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, itemError.getEffectiveNodeOrientation());
        });
    }

