    /// Verifies that validation summaries route accessibility focus to the current invalid input.
    @Test
    void validationSummaryRoutesAccessibleFocusAcrossInvalidInputs() {
        FxTestUtils.runOnFxThread(() -> {
            M3TextField nameField = new M3TextField();
            M3TextInputLayout nameLayout = new M3TextInputLayout(nameField, "Name", "Required");
            nameLayout.setValidator(M3TextInputValidators.required("Name is required"));

            M3TextField emailField = new M3TextField();
            M3TextInputLayout emailLayout = new M3TextInputLayout(emailField, "Email", "Required");
            emailLayout.setValidator(M3TextInputValidators.required("Email is required"));

            M3Button outside = new M3Button("Outside");
            M3FormValidator validator = new M3FormValidator(nameLayout, emailLayout);
            M3ValidationSummary summary = new M3ValidationSummary(validator);
            assertFalse(validator.validate());

            VBox root = new VBox(8.0, nameLayout, emailLayout, summary, outside);
            Stage stage = new Stage();
            try {
                Scene scene = new Scene(root, 520.0, 320.0);
                M3ThemeManager.install(scene, M3Theme.defaultTheme());
                stage.setScene(scene);
                stage.show();
                root.applyCss();
                root.layout();

                assertEquals(2, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                assertSame(nameLayout, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_AT_INDEX, 0));
                assertSame(emailLayout, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_AT_INDEX, 1));
                assertSame(nameField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
                VBox items = assertInstanceOf(
                        VBox.class,
                        summary.lookup("." + M3ValidationSummary.ITEMS_STYLE_CLASS)
                );
                Node nameSummaryItem = items.getChildren().get(0);
                Node emailSummaryItem = items.getChildren().get(1);

                nameSummaryItem.requestFocus();
                assertTrue(nameSummaryItem.isFocused());

                nameSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.DOWN));

                assertTrue(emailSummaryItem.isFocused());

                emailSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.DOWN));

                assertTrue(emailSummaryItem.isFocused());

                emailSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.UP));

                assertTrue(nameSummaryItem.isFocused());

                nameSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.END));

                assertTrue(emailSummaryItem.isFocused());

                emailSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.HOME));

                assertTrue(nameSummaryItem.isFocused());

                nameSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.SPACE));

                assertTrue(nameField.isFocused());
                assertSame(nameField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                summary.executeAccessibleAction(AccessibleAction.SHOW_ITEM, emailLayout);

                assertTrue(emailField.isFocused());
                assertSame(emailField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                summary.executeAccessibleAction(AccessibleAction.SHOW_ITEM, List.of(nameField));

                assertTrue(nameField.isFocused());
                assertSame(nameField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                emailSummaryItem.requestFocus();
                assertTrue(emailSummaryItem.isFocused());

                emailSummaryItem.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, KeyCode.ENTER));

                assertTrue(emailField.isFocused());
                assertSame(emailField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                summary.executeAccessibleAction(AccessibleAction.SHOW_ITEM, 1);

                assertTrue(emailField.isFocused());
                assertSame(emailField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                emailField.setText("support@example.com");

                assertEquals(1, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                assertSame(nameLayout, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_AT_INDEX, 0));
                assertSame(nameField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                outside.requestFocus();

                assertTrue(outside.isFocused());
                assertSame(nameField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                nameField.setText("Ada");

                assertEquals(0, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                assertNull(summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
            } finally {
                stage.close();
            }
        });
    }

    /// Verifies that form validators focus the first reachable invalid input.
    @Test
    void formValidatorFocusSkipsInvalidInputsHiddenByAncestors() {
        FxTestUtils.runOnFxThread(() -> {
            M3TextField hiddenField = new M3TextField();
            M3TextInputLayout hiddenLayout = new M3TextInputLayout(hiddenField, "Hidden", "Required");
            hiddenLayout.setValidator(M3TextInputValidators.required("Hidden is required"));
            Pane hiddenAncestor = new Pane(hiddenLayout);
            hiddenAncestor.setVisible(false);

            M3TextField visibleField = new M3TextField();
            M3TextInputLayout visibleLayout = new M3TextInputLayout(visibleField, "Visible", "Required");
            visibleLayout.setValidator(M3TextInputValidators.required("Visible is required"));

            M3Button outside = new M3Button("Outside");
            M3FormValidator validator = new M3FormValidator(hiddenLayout, visibleLayout);
            VBox root = new VBox(8.0, hiddenAncestor, visibleLayout, outside);
            Stage stage = new Stage();
            try {
                Scene scene = new Scene(root, 520.0, 280.0);
                M3ThemeManager.install(scene, M3Theme.defaultTheme());
                stage.setScene(scene);
                stage.show();
                root.applyCss();
                root.layout();

                assertFalse(validator.validate());
                assertTrue(validator.focusFirstInvalidInput());
                assertTrue(visibleField.isFocused());
                assertFalse(hiddenField.isFocused());

                outside.requestFocus();
                visibleLayout.setVisible(false);

                assertFalse(validator.focusFirstInvalidInput());
                assertTrue(outside.isFocused());
                assertFalse(hiddenField.isFocused());
                assertFalse(visibleField.isFocused());
            } finally {
                stage.close();
            }
        });
    }

    /// Verifies that validation summary accessibility skips invalid inputs hidden by ancestors.
    @Test
    void validationSummarySkipsInvalidInputsHiddenByAncestors() {
        FxTestUtils.runOnFxThread(() -> {
            M3TextField hiddenField = new M3TextField();
            M3TextInputLayout hiddenLayout = new M3TextInputLayout(hiddenField, "Hidden", "Required");
            hiddenLayout.setValidator(M3TextInputValidators.required("Hidden is required"));
            Pane hiddenAncestor = new Pane(hiddenLayout);
            hiddenAncestor.setVisible(false);

            M3TextField visibleField = new M3TextField();
            M3TextInputLayout visibleLayout = new M3TextInputLayout(visibleField, "Visible", "Required");
            visibleLayout.setValidator(M3TextInputValidators.required("Visible is required"));

            M3Button outside = new M3Button("Outside");
            M3FormValidator validator = new M3FormValidator(hiddenLayout, visibleLayout);
            M3ValidationSummary summary = new M3ValidationSummary(validator);
            VBox root = new VBox(8.0, hiddenAncestor, visibleLayout, summary, outside);
            Stage stage = new Stage();
            try {
                Scene scene = new Scene(root, 520.0, 360.0);
                M3ThemeManager.install(scene, M3Theme.defaultTheme());
                stage.setScene(scene);
                stage.show();
                root.applyCss();
                root.layout();

                assertFalse(validator.validate());
                root.applyCss();
                root.layout();

                PseudoClass empty = PseudoClass.getPseudoClass("empty");
                assertEquals(2, summary.getInvalidInputCount());
                assertEquals(1, summary.getVisibleInvalidInputCount());
                assertFalse(summary.getPseudoClassStates().contains(empty));
                assertFalse(summary.isInvalidInputShown(hiddenLayout));
                assertFalse(summary.isInvalidInputReachable(hiddenLayout));
                assertTrue(summary.isInvalidInputShown(visibleLayout));
                assertTrue(summary.isInvalidInputReachable(visibleLayout));
                assertEquals(1, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                assertSame(visibleLayout, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_AT_INDEX, 0));
                assertNull(summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_AT_INDEX, 1));
                assertSame(visibleField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
                VBox items = assertInstanceOf(
                        VBox.class,
                        summary.lookup("." + M3ValidationSummary.ITEMS_STYLE_CLASS)
                );
                assertEquals(1, items.getChildren().size());
                Label itemLabel = assertInstanceOf(
                        Label.class,
                        items.getChildren().get(0).lookup("." + M3ValidationSummary.ITEM_LABEL_STYLE_CLASS)
                );
                assertEquals("Visible", itemLabel.getText());

                outside.requestFocus();
                assertFalse(summary.focusInput(hiddenLayout));

                assertTrue(outside.isFocused());
                assertFalse(hiddenField.isFocused());

                summary.executeAccessibleAction(AccessibleAction.SHOW_ITEM, hiddenLayout);

                assertTrue(outside.isFocused());
                assertFalse(hiddenField.isFocused());

                summary.executeAccessibleAction(AccessibleAction.SHOW_ITEM, 0);

                assertTrue(visibleField.isFocused());
                assertSame(visibleField, summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

                hiddenAncestor.setVisible(true);
                root.applyCss();
                root.layout();

                assertTrue(summary.isInvalidInputShown(hiddenLayout));
                assertTrue(summary.isInvalidInputReachable(hiddenLayout));
                assertEquals(2, summary.getVisibleInvalidInputCount());
                assertEquals(2, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                assertEquals(2, summary.lookupAll("." + M3ValidationSummary.ITEM_STYLE_CLASS).size());

                visibleLayout.setDisable(true);
                root.applyCss();
                root.layout();

                assertFalse(summary.isInvalidInputShown(visibleLayout));
                assertFalse(summary.isInvalidInputReachable(visibleLayout));
                assertEquals(1, summary.getVisibleInvalidInputCount());
                assertEquals(1, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                items = assertInstanceOf(
                        VBox.class,
                        summary.lookup("." + M3ValidationSummary.ITEMS_STYLE_CLASS)
                );
                assertEquals(1, items.getChildren().size());
                itemLabel = assertInstanceOf(
                        Label.class,
                        items.getChildren().get(0).lookup("." + M3ValidationSummary.ITEM_LABEL_STYLE_CLASS)
                );
                assertEquals("Hidden", itemLabel.getText());

                hiddenAncestor.setVisible(false);
                root.applyCss();
                root.layout();

                assertFalse(summary.isShowingSummary());
                assertEquals(0, summary.getVisibleInvalidInputCount());
                assertTrue(summary.getPseudoClassStates().contains(empty));
                assertTrue(summary.lookupAll("." + M3ValidationSummary.ITEM_STYLE_CLASS).isEmpty());
                assertEquals(0, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));

                hiddenAncestor.setVisible(true);
                visibleLayout.setDisable(false);
                root.applyCss();
                root.layout();

                assertTrue(summary.isShowingSummary());
                assertEquals(2, summary.getVisibleInvalidInputCount());
                assertFalse(summary.getPseudoClassStates().contains(empty));
                assertEquals(2, summary.lookupAll("." + M3ValidationSummary.ITEM_STYLE_CLASS).size());

                outside.requestFocus();
                summary.setVisible(false);
                root.applyCss();
                root.layout();

                assertEquals(0, summary.queryAccessibleAttribute(AccessibleAttribute.ITEM_COUNT));
                assertNull(summary.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
                assertFalse(summary.focusInput(visibleLayout));
                assertTrue(outside.isFocused());
            } finally {
                stage.close();
            }
        });
    }

    /// Verifies that selection controls render selected, indeterminate, and disabled states.
    @Tier2Test
    @Test
    void selectionSnapshotRendersStateMatrix() {
        FxTestUtils.runOnFxThread(() -> {
            M3CheckBox uncheckedCheckBox = new M3CheckBox("Unchecked");
            M3CheckBox checkedCheckBox = createCheckBox("Checked", true);
            M3CheckBox indeterminateCheckBox = new M3CheckBox("Indeterminate");
            indeterminateCheckBox.setIndeterminate(true);
            M3CheckBox disabledUncheckedCheckBox = new M3CheckBox("Disabled unchecked");
            M3CheckBox disabledCheckedCheckBox = createCheckBox("Disabled checked", true);
            M3CheckBox disabledIndeterminateCheckBox = new M3CheckBox("Disabled indeterminate");
            disabledIndeterminateCheckBox.setIndeterminate(true);
            disabledUncheckedCheckBox.setDisable(true);
            disabledCheckedCheckBox.setDisable(true);
            disabledIndeterminateCheckBox.setDisable(true);

            M3RadioButton uncheckedRadioButton = new M3RadioButton("Radio off");
            M3RadioButton selectedRadioButton = createRadioButton("Radio on", true);
            M3RadioButton disabledUncheckedRadioButton = new M3RadioButton("Disabled off");
            M3RadioButton disabledSelectedRadioButton = createRadioButton("Disabled on", true);
            disabledUncheckedRadioButton.setDisable(true);
            disabledSelectedRadioButton.setDisable(true);

            M3Switch offSwitch = new M3Switch("Switch off");
            M3Switch onSwitch = createSwitch("Switch on", true);
            M3Switch disabledOffSwitch = new M3Switch("Disabled off");
            M3Switch disabledOnSwitch = createSwitch("Disabled on", true);
            disabledOffSwitch.setDisable(true);
            disabledOnSwitch.setDisable(true);

            FlowPane row = new FlowPane(
                    20.0,
                    16.0,
                    uncheckedCheckBox,
                    checkedCheckBox,
                    indeterminateCheckBox,
                    disabledUncheckedCheckBox,
                    disabledCheckedCheckBox,
                    disabledIndeterminateCheckBox,
                    uncheckedRadioButton,
                    selectedRadioButton,
                    disabledUncheckedRadioButton,
                    disabledSelectedRadioButton,
                    offSwitch,
                    onSwitch,
                    disabledOffSwitch,
                    disabledOnSwitch
            );
            row.setPrefWrapLength(720.0);
            row.setStyle("-fx-background-color: white; -fx-padding: 20px; " + visualTestColors());
            Scene scene = new Scene(row, 760.0, 280.0);

            M3ThemeManager.install(scene, M3Theme.defaultTheme());
            row.applyCss();
            row.resize(760.0, 280.0);
            row.layout();

            WritableImage image = snapshotImageOnFxThread(row);
            Region checkedBox = lookupRegion(checkedCheckBox, ".box");
            Region indeterminateBox = lookupRegion(indeterminateCheckBox, ".box");
            Region indeterminateMark = lookupRegion(indeterminateCheckBox, ".mark");
            assertSnapshotNodeBorderContainsContrast(image, lookupRegion(uncheckedCheckBox, ".box"), Color.WHITE, 0.08);
            assertSnapshotNodeContainsContrast(image, checkedBox, Color.WHITE, 0.1);
            assertSnapshotNodeContainsContrast(image, lookupRegion(checkedCheckBox, ".mark"), Color.rgb(84, 50, 185), 0.1);
            assertSnapshotNodeContainsContrast(image, indeterminateBox, Color.WHITE, 0.1);
            assertSnapshotNodeContainsContrast(
                    image,
                    indeterminateMark,
                    Color.rgb(84, 50, 185),
                    0.1
            );
            assertEquals(12.0, indeterminateMark.getLayoutBounds().getWidth(), 0.0001);
            assertEquals(2.0, indeterminateMark.getLayoutBounds().getHeight(), 0.0001);
            Color checkedBoxFill = snapshotNodePixel(image, checkedBox, checkedBox.getWidth() / 2.0, 3.0);
            Color indeterminateBoxTop = snapshotNodePixel(
                    image,
                    indeterminateBox,
                    indeterminateBox.getWidth() / 2.0,
                    5.0
            );
            Color indeterminateDash = snapshotNodePixel(
                    image,
                    indeterminateBox,
                    indeterminateBox.getWidth() / 2.0,
                    indeterminateBox.getHeight() / 2.0
            );
            Color indeterminateBoxBottom = snapshotNodePixel(
                    image,
                    indeterminateBox,
                    indeterminateBox.getWidth() / 2.0,
                    indeterminateBox.getHeight() - 5.0
            );
            assertColorNear(
                    indeterminateBoxTop,
                    checkedBoxFill,
                    0.24,
                    "indeterminate checkbox top fill"
            );
            assertColorNear(
                    indeterminateDash,
                    Color.WHITE,
                    0.18,
                    "indeterminate checkbox dash"
            );
            assertColorNear(
                    indeterminateBoxBottom,
                    checkedBoxFill,
                    0.24,
                    "indeterminate checkbox bottom fill"
            );
            assertTrue(colorDistance(indeterminateBoxTop, indeterminateDash) > 0.6);
            assertTrue(colorDistance(indeterminateBoxBottom, indeterminateDash) > 0.6);
            assertSnapshotNodeContainsContrast(image, lookupRegion(disabledUncheckedCheckBox, ".box"), Color.WHITE, 0.03);
            assertSnapshotNodeContainsContrast(image, lookupRegion(disabledCheckedCheckBox, ".box"), Color.WHITE, 0.03);
            assertSnapshotNodeContainsContrast(
                    image,
                    lookupRegion(disabledIndeterminateCheckBox, ".mark"),
                    Color.rgb(30, 28, 32),
                    0.1
            );
            assertSnapshotNodeContainsContrast(image, lookupShape(uncheckedRadioButton, ".ring"), Color.WHITE, 0.08);
            Shape selectedRadioDot = lookupShape(selectedRadioButton, ".dot");
            Shape disabledSelectedRadioDot = lookupShape(disabledSelectedRadioButton, ".dot");
            assertSnapshotNodeContainsContrast(image, selectedRadioDot, Color.WHITE, 0.1);
            assertRadioButtonIndicatorRenderedCentersAligned(image, selectedRadioButton, "selected radio button");
            assertSnapshotNodeContainsContrast(image, lookupShape(disabledUncheckedRadioButton, ".ring"), Color.WHITE, 0.03);
            assertSnapshotNodeContainsContrast(image, disabledSelectedRadioDot, Color.WHITE, 0.03);
            Color selectedRadioDotPixel = snapshotNodePixel(
                    image,
                    selectedRadioDot,
                    selectedRadioDot.getBoundsInLocal().getCenterX(),
                    selectedRadioDot.getBoundsInLocal().getCenterY()
            );
            Color disabledSelectedRadioDotPixel = snapshotNodePixel(
                    image,
                    disabledSelectedRadioDot,
                    disabledSelectedRadioDot.getBoundsInLocal().getCenterX(),
                    disabledSelectedRadioDot.getBoundsInLocal().getCenterY()
            );
            assertTrue(
                    colorDistance(disabledSelectedRadioDotPixel, Color.WHITE)
                            < colorDistance(selectedRadioDotPixel, Color.WHITE) * 0.8,
                    () -> "disabled selected radio dot should composite toward the surface: enabled="
                            + selectedRadioDotPixel + ", disabled=" + disabledSelectedRadioDotPixel
            );
            assertSnapshotNodeBorderContainsContrast(image, lookupRegion(offSwitch, ".box"), Color.WHITE, 0.08);
            assertSnapshotNodeContainsContrast(image, lookupRegion(onSwitch, ".box"), Color.WHITE, 0.1);
            assertSnapshotNodeContainsContrast(image, lookupRegion(onSwitch, ".thumb"), Color.rgb(84, 50, 185), 0.1);
            assertSnapshotNodeContainsContrast(image, lookupRegion(disabledOffSwitch, ".box"), Color.WHITE, 0.03);
            assertSnapshotNodeContainsContrast(image, lookupRegion(disabledOnSwitch, ".thumb"), Color.WHITE, 0.03);
            writeVisualSnapshot(image, java.nio.file.Path.of(
                    "build",
                    "reports",
                    "m3fx-visual",
                    "visual-selection-states.png"
            ));
            assertRenderedTextNodesStayInsideLayout(row);
            assertFixedTargetControlsKeepCenteredContent(row);
        });
    }

