    /// Returns whether the tested button ripple has reached its expanded pressed frame.
    private static boolean buttonRippleIsFullyExpanded(AtomicReference<@Nullable M3Button> buttonReference) {
        @Nullable Region ripple = buttonRipple(buttonReference);
        return ripple != null
                && ripple.getOpacity() > 0.0
                && ripple.getScaleX() >= 0.98
                && ripple.getScaleY() >= 0.98;
    }

    /// Returns whether the tested button ripple is visibly fading below a captured release opacity.
    private static boolean buttonRippleOpacityFadedBelow(
            AtomicReference<@Nullable M3Button> buttonReference,
            AtomicReference<@Nullable Double> baselineOpacityReference
    ) {
        @Nullable Region ripple = buttonRipple(buttonReference);
        @Nullable Double baselineOpacity = baselineOpacityReference.get();
        if (ripple == null || baselineOpacity == null) {
            return false;
        }

        double opacity = ripple.getOpacity();
        return opacity > 0.0 && opacity < baselineOpacity - 0.001;
    }

    /// Returns whether the tested button ripple has completed release fade-out.
    private static boolean buttonRippleOpacityCleared(AtomicReference<@Nullable M3Button> buttonReference) {
        @Nullable Region ripple = buttonRipple(buttonReference);
        return ripple != null && ripple.getOpacity() <= 0.0001;
    }

    /// Returns the tested button ripple region after applying current layout state.
    private static @Nullable Region buttonRipple(AtomicReference<@Nullable M3Button> buttonReference) {
        @Nullable M3Button button = buttonReference.get();
        if (button == null) {
            return null;
        }

        button.applyCss();
        button.layout();
        @Nullable Node rippleNode = button.lookup(".m3-ripple");
        return rippleNode instanceof Region ripple ? ripple : null;
    }

    /// Shows an outlined text input layout configured for observable presentation animations.
    private static void showObservableTextInputLayout(
            AtomicReference<@Nullable Stage> stageReference,
            AtomicReference<@Nullable Pane> rootReference,
            AtomicReference<@Nullable M3TextInputLayout> layoutReference,
            boolean showSupportingText
    ) {
        M3TextField textField = createTextField("", M3TextInputVariant.OUTLINED);
        textField.setPrefWidth(260.0);
        M3TextInputLayout layout = new M3TextInputLayout(textField);
        layout.setLabelText("Email");
        layout.setClearButtonEnabled(true);
        layout.setPrefWidth(260.0);

        Pane root = new Pane(layout);
        layout.resizeRelocate(20.0, 20.0, 260.0, 96.0);
        Scene scene = new Scene(root, 320.0, 140.0);
        Stage stage = new Stage();

        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        M3MotionSettings.setReducedMotionRequested(root, false);
        FxTestUtils.setMotionScheme(root, observableTestMotionScheme());
        stage.setScene(scene);
        stage.show();
        root.applyCss();
        root.layout();

        Path outline = assertInstanceOf(Path.class, layout.lookup("." + M3TextInputLayout.OUTLINE_STYLE_CLASS));
        assertEquals(0.0, outlineNotchGap(outline), 0.0001);

        stageReference.set(stage);
        rootReference.set(root);
        layoutReference.set(layout);
        textField.setText("alpha");
        if (showSupportingText) {
            layout.setSupportingText("Helper text");
        }
    }

    /// Returns whether a text input layout is rendering a floating-label intermediate frame.
    private static boolean textInputLayoutFloatingPresentationIsAnimating(
            AtomicReference<@Nullable M3TextInputLayout> layoutReference
    ) {
        @Nullable M3TextInputLayout layout = layoutReference.get();
        if (layout == null) {
            return false;
        }

        layout.applyCss();
        layout.layout();
        @Nullable Node labelNode = layout.lookup("." + M3TextInputLayout.LABEL_STYLE_CLASS);
        @Nullable Node outlineNode = layout.lookup("." + M3TextInputLayout.OUTLINE_STYLE_CLASS);
        if (!(labelNode instanceof Label label) || !(outlineNode instanceof Path outline)) {
            return false;
        }

        M3IconButton clearButton = textInputClearButton(layout);
        return isBetweenExclusive(label.getOpacity(), 0.72, 1.0)
                && isBetweenExclusive(Math.abs(label.getTranslateY()), 0.0, 4.0)
                && outlineNotchGap(outline) > 0.5
                && isBetweenExclusive(clearButton.getOpacity(), 0.0, 1.0)
                && isBetweenExclusive(clearButton.getScaleX(), 0.86, 1.0)
                && isBetweenExclusive(clearButton.getScaleY(), 0.86, 1.0);
    }

    /// Returns whether a text input layout is rendering a supporting-row intermediate frame.
    private static boolean textInputLayoutSupportingRowPresentationIsAnimating(
            AtomicReference<@Nullable M3TextInputLayout> layoutReference
    ) {
        @Nullable M3TextInputLayout layout = layoutReference.get();
        if (layout == null) {
            return false;
        }

        layout.applyCss();
        layout.layout();
        @Nullable Node supportingRowNode = layout.lookup("." + M3TextInputLayout.SUPPORTING_ROW_STYLE_CLASS);
        if (!(supportingRowNode instanceof HBox supportingRow)) {
            return false;
        }

        return isBetweenExclusive(supportingRow.getOpacity(), 0.0, 1.0)
                && isBetweenExclusive(Math.abs(supportingRow.getTranslateY()), 0.0, 4.0);
    }

    /// Returns whether all text input presentation channels are rendering intermediate frames.
    private static boolean textInputLayoutFullPresentationIsAnimating(
            AtomicReference<@Nullable M3TextInputLayout> layoutReference
    ) {
        return textInputLayoutFloatingPresentationIsAnimating(layoutReference)
                && textInputLayoutSupportingRowPresentationIsAnimating(layoutReference);
    }

    /// Verifies a floating-label and clear-button intermediate frame on a text input layout.
    private static void assertTextInputLayoutFloatingPresentationIntermediate(M3TextInputLayout layout) {
        Label label = assertInstanceOf(Label.class, layout.lookup("." + M3TextInputLayout.LABEL_STYLE_CLASS));
        Path outline = assertInstanceOf(Path.class, layout.lookup("." + M3TextInputLayout.OUTLINE_STYLE_CLASS));
        M3IconButton clearButton = textInputClearButton(layout);

        assertBetween(label.getOpacity(), 0.72, 1.0, "floating label opacity");
        assertBetween(Math.abs(label.getTranslateY()), 0.0, 4.0, "floating label translateY");
        assertTrue(outlineNotchGap(outline) > 0.5, () -> "outlineNotchGap=" + outlineNotchGap(outline));
        assertBetween(clearButton.getOpacity(), 0.0, 1.0, "clear button opacity");
        assertBetween(clearButton.getScaleX(), 0.86, 1.0, "clear button scaleX");
        assertBetween(clearButton.getScaleY(), 0.86, 1.0, "clear button scaleY");
    }

    /// Verifies a supporting-row intermediate frame on a text input layout.
    private static void assertTextInputLayoutSupportingRowPresentationIntermediate(M3TextInputLayout layout) {
        HBox supportingRow = assertInstanceOf(
                HBox.class,
                layout.lookup("." + M3TextInputLayout.SUPPORTING_ROW_STYLE_CLASS)
        );

        assertBetween(supportingRow.getOpacity(), 0.0, 1.0, "supporting row opacity");
        assertBetween(Math.abs(supportingRow.getTranslateY()), 0.0, 4.0, "supporting row translateY");
    }

    /// Verifies that text input presentation state is settled after motion is disabled.
    private static void assertTextInputLayoutPresentationSettled(M3TextInputLayout layout) {
        Label label = assertInstanceOf(Label.class, layout.lookup("." + M3TextInputLayout.LABEL_STYLE_CLASS));
        Path outline = assertInstanceOf(Path.class, layout.lookup("." + M3TextInputLayout.OUTLINE_STYLE_CLASS));
        M3IconButton clearButton = textInputClearButton(layout);
        HBox supportingRow = assertInstanceOf(
                HBox.class,
                layout.lookup("." + M3TextInputLayout.SUPPORTING_ROW_STYLE_CLASS)
        );

        assertEquals(1.0, label.getOpacity(), 0.0001);
        assertEquals(0.0, label.getTranslateY(), 0.0001);
        assertTrue(outlineNotchGap(outline) > 0.5, () -> "outlineNotchGap=" + outlineNotchGap(outline));
        assertEquals(1.0, clearButton.getOpacity(), 0.0001);
        assertEquals(1.0, clearButton.getScaleX(), 0.0001);
        assertEquals(1.0, clearButton.getScaleY(), 0.0001);
        assertEquals(1.0, supportingRow.getOpacity(), 0.0001);
        assertEquals(0.0, supportingRow.getTranslateY(), 0.0001);
    }

    /// Returns whether a trailing icon button is rendering a visible ripple frame.
    private static boolean trailingIconRippleIsVisible(AtomicReference<@Nullable M3IconButton> buttonReference) {
        @Nullable M3IconButton button = buttonReference.get();
        if (button == null) {
            return false;
        }

        button.applyCss();
        button.layout();
        @Nullable Node rippleNode = button.lookup(".m3-ripple");
        if (!(rippleNode instanceof Region ripple)) {
            return false;
        }

        return ripple.getOpacity() > 0.0
                && ripple.getScaleX() > 0.0
                && ripple.getScaleY() > 0.0;
    }

    /// Returns whether search view results are rendering an intermediate exit transition.
    private static boolean searchViewResultsExitIsIntermediate(AtomicReference<@Nullable Region> resultsReference) {
        @Nullable Region results = resultsReference.get();
        if (results == null) {
            return false;
        }

        results.applyCss();
        results.layout();
        return results.isVisible()
                && results.isManaged()
                && isBetweenExclusive(results.getOpacity(), 0.0, 1.0)
                && isBetweenExclusive(Math.abs(results.getTranslateY()), 0.0, 8.0);
    }

    /// Describes search view result presentation state for motion timeout diagnostics.
    private static String describeSearchViewResults(AtomicReference<@Nullable Region> resultsReference) {
        @Nullable Region results = resultsReference.get();
        if (results == null) {
            return "results=null";
        }
        return "visible=" + results.isVisible()
                + ", managed=" + results.isManaged()
                + ", opacity=" + results.getOpacity()
                + ", translateY=" + results.getTranslateY();
    }

    /// Verifies the resolved logical text alignment of a form row.
    private static void assertFormRowTextAlignment(
            M3FormRow row,
            Pos startAlignment,
            Pos endAlignment,
            TextAlignment textAlignment
    ) {
        VBox textColumn = assertInstanceOf(VBox.class, row.lookup("." + M3FormRow.TEXT_COLUMN_STYLE_CLASS));
        Label label = assertInstanceOf(Label.class, row.lookup("." + M3FormRow.LABEL_STYLE_CLASS));
        Label supporting = assertInstanceOf(Label.class, row.lookup("." + M3FormRow.SUPPORTING_TEXT_STYLE_CLASS));
        StackPane contentSlot = assertInstanceOf(StackPane.class, row.lookup("." + M3FormRow.CONTENT_STYLE_CLASS));
        StackPane trailingSlot = assertInstanceOf(StackPane.class, row.lookup("." + M3FormRow.TRAILING_STYLE_CLASS));

        assertEquals(startAlignment, textColumn.getAlignment());
        assertEquals(startAlignment, label.getAlignment());
        assertEquals(startAlignment, supporting.getAlignment());
        assertEquals(textAlignment, label.getTextAlignment());
        assertEquals(textAlignment, supporting.getTextAlignment());
        assertEquals(startAlignment, contentSlot.getAlignment());
        assertEquals(endAlignment, trailingSlot.getAlignment());
    }

    /// Verifies the resolved logical text alignment of a form section.
    private static void assertFormSectionTextAlignment(
            M3FormSection section,
            Pos topAlignment,
            Pos centerAlignment,
            TextAlignment textAlignment,
            NodeOrientation nodeOrientation
    ) {
        VBox header = assertInstanceOf(VBox.class, section.lookup("." + M3FormSection.HEADER_STYLE_CLASS));
        VBox content = assertInstanceOf(VBox.class, section.lookup("." + M3FormSection.CONTENT_STYLE_CLASS));
        Label title = assertInstanceOf(Label.class, section.lookup("." + M3FormSection.TITLE_STYLE_CLASS));
        Label supporting = assertInstanceOf(
                Label.class,
                section.lookup("." + M3FormSection.SUPPORTING_TEXT_STYLE_CLASS)
        );

        assertEquals(topAlignment, header.getAlignment());
        assertEquals(topAlignment, content.getAlignment());
        assertEquals(nodeOrientation, header.getEffectiveNodeOrientation());
        assertEquals(nodeOrientation, content.getEffectiveNodeOrientation());
        assertEquals(NodeOrientation.LEFT_TO_RIGHT, title.getEffectiveNodeOrientation());
        assertEquals(NodeOrientation.LEFT_TO_RIGHT, supporting.getEffectiveNodeOrientation());
        assertEquals(centerAlignment, title.getAlignment());
        assertEquals(centerAlignment, supporting.getAlignment());
        assertEquals(textAlignment, title.getTextAlignment());
        assertEquals(textAlignment, supporting.getTextAlignment());
    }

    /// Verifies the resolved logical slot geometry of a search bar.
    private static void assertSearchBarUsesLogicalGeometry(M3SearchBar searchBar, boolean rightToLeft) {
        searchBar.applyCss();
        searchBar.layout();

        Region leadingSlot = lookupRegion(searchBar, "." + M3SearchBar.LEADING_STYLE_CLASS);
        Region trailingBox = lookupRegion(searchBar, "." + M3SearchBar.TRAILING_STYLE_CLASS);
        TextInputControl editor = searchBarEditor(searchBar);
        Bounds leadingBounds = leadingSlot.localToScene(leadingSlot.getBoundsInLocal());
        Bounds editorBounds = editor.localToScene(editor.getBoundsInLocal());
        Bounds trailingBounds = trailingBox.localToScene(trailingBox.getBoundsInLocal());

        if (rightToLeft) {
            assertTrue(trailingBounds.getCenterX() < editorBounds.getCenterX(),
                    () -> describeSearchBarGeometry(leadingBounds, editorBounds, trailingBounds));
            assertTrue(editorBounds.getCenterX() < leadingBounds.getCenterX(),
                    () -> describeSearchBarGeometry(leadingBounds, editorBounds, trailingBounds));
            assertEquals(NodeOrientation.RIGHT_TO_LEFT, searchBar.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.RIGHT_TO_LEFT, editor.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.RIGHT_TO_LEFT, trailingBox.getEffectiveNodeOrientation());
        } else {
            assertTrue(leadingBounds.getCenterX() < editorBounds.getCenterX(),
                    () -> describeSearchBarGeometry(leadingBounds, editorBounds, trailingBounds));
            assertTrue(editorBounds.getCenterX() < trailingBounds.getCenterX(),
                    () -> describeSearchBarGeometry(leadingBounds, editorBounds, trailingBounds));
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, searchBar.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, editor.getEffectiveNodeOrientation());
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, trailingBox.getEffectiveNodeOrientation());
        }
    }

    /// Verifies the resolved logical geometry of an active search view.
    private static void assertSearchViewUsesLogicalGeometry(M3SearchView searchView, boolean rightToLeft) {
        searchView.applyCss();
        searchView.layout();

        assertSearchBarUsesLogicalGeometry(searchViewSearchBar(searchView), rightToLeft);
        assertEquals(
                rightToLeft ? NodeOrientation.RIGHT_TO_LEFT : NodeOrientation.LEFT_TO_RIGHT,
                searchViewResultsContainer(searchView).getEffectiveNodeOrientation()
        );

        for (Node result : searchView.getResults()) {
            assertEquals(
                    rightToLeft ? NodeOrientation.RIGHT_TO_LEFT : NodeOrientation.LEFT_TO_RIGHT,
                    result.getEffectiveNodeOrientation()
            );
        }

        M3ListItem secondResult = assertInstanceOf(M3ListItem.class, searchView.getResults().get(1));
        Node trailing = assertInstanceOf(Node.class, secondResult.getTrailing());
        Bounds rowBounds = secondResult.localToScene(secondResult.getBoundsInLocal());
        Bounds trailingBounds = trailing.localToScene(trailing.getBoundsInLocal());

        if (rightToLeft) {
            assertTrue(trailingBounds.getCenterX() < rowBounds.getCenterX(),
                    () -> "rowBounds=" + rowBounds + ", trailingBounds=" + trailingBounds);
        } else {
            assertTrue(trailingBounds.getCenterX() > rowBounds.getCenterX(),
                    () -> "rowBounds=" + rowBounds + ", trailingBounds=" + trailingBounds);
        }
    }

    /// Describes search bar slot geometry for assertion failures.
    private static String describeSearchBarGeometry(
            Bounds leadingBounds,
            Bounds editorBounds,
            Bounds trailingBounds
    ) {
        return "leadingBounds=" + leadingBounds
                + ", editorBounds=" + editorBounds
                + ", trailingBounds=" + trailingBounds;
    }

    /// Verifies the resolved logical geometry of a text input layout.
    private static void assertTextInputLayoutUsesLogicalGeometry(M3TextInputLayout layout, boolean rightToLeft) {
        layout.applyCss();
        layout.layout();

        Region inputContainer = lookupRegion(layout, "." + M3TextInputLayout.INPUT_CONTAINER_STYLE_CLASS);
        Region leadingSlot = lookupRegion(layout, "." + M3TextInputLayout.LEADING_STYLE_CLASS);
        Region trailingSlot = lookupRegion(layout, "." + M3TextInputLayout.TRAILING_STYLE_CLASS);
        Label label = assertInstanceOf(Label.class, layout.lookup("." + M3TextInputLayout.LABEL_STYLE_CLASS));
        Label supportingLabel = assertInstanceOf(
                Label.class,
                layout.lookup("." + M3TextInputLayout.SUPPORTING_TEXT_STYLE_CLASS)
        );
        Label counterLabel = assertInstanceOf(Label.class, layout.lookup("." + M3TextInputLayout.COUNTER_STYLE_CLASS));
        Path outline = assertInstanceOf(Path.class, layout.lookup("." + M3TextInputLayout.OUTLINE_STYLE_CLASS));
        TextInputControl input = Objects.requireNonNull(layout.getInput(), "input");

        Bounds containerBounds = inputContainer.localToScene(inputContainer.getBoundsInLocal());
        Bounds leadingBounds = leadingSlot.localToScene(leadingSlot.getBoundsInLocal());
        Bounds trailingBounds = trailingSlot.localToScene(trailingSlot.getBoundsInLocal());
        Bounds labelBounds = label.localToScene(label.getBoundsInLocal());
        Bounds supportingBounds = supportingLabel.localToScene(supportingLabel.getBoundsInLocal());
        Bounds counterBounds = counterLabel.localToScene(counterLabel.getBoundsInLocal());

        if (rightToLeft) {
            assertTrue(leadingBounds.getMinX() > containerBounds.getCenterX(),
                    () -> describeTextInputLayoutGeometry(
                            containerBounds,
                            leadingBounds,
                            trailingBounds,
                            labelBounds,
                            supportingBounds,
                            counterBounds
                    ));
            if (hasRenderableBounds(trailingSlot)) {
                assertTrue(trailingBounds.getMaxX() < containerBounds.getCenterX(),
                        () -> describeTextInputLayoutGeometry(
                                containerBounds,
                                leadingBounds,
                                trailingBounds,
                                labelBounds,
                                supportingBounds,
                                counterBounds
                        ));
            }
            assertTrue(labelBounds.getCenterX() > containerBounds.getCenterX(),
                    () -> describeTextInputLayoutGeometry(
                            containerBounds,
                            leadingBounds,
                            trailingBounds,
                            labelBounds,
                            supportingBounds,
                            counterBounds
                    ));
            assertTrue(supportingBounds.getCenterX() > counterBounds.getCenterX(),
                    () -> describeTextInputLayoutGeometry(
                            containerBounds,
                            leadingBounds,
                            trailingBounds,
                            labelBounds,
                            supportingBounds,
                            counterBounds
                    ));
            assertEquals(NodeOrientation.RIGHT_TO_LEFT, input.getEffectiveNodeOrientation());
        } else {
            assertTrue(leadingBounds.getMaxX() < containerBounds.getCenterX(),
                    () -> describeTextInputLayoutGeometry(
                            containerBounds,
                            leadingBounds,
                            trailingBounds,
                            labelBounds,
                            supportingBounds,
                            counterBounds
                    ));
            if (hasRenderableBounds(trailingSlot)) {
                assertTrue(trailingBounds.getMinX() > containerBounds.getCenterX(),
                        () -> describeTextInputLayoutGeometry(
                                containerBounds,
                                leadingBounds,
                                trailingBounds,
                                labelBounds,
                                supportingBounds,
                                counterBounds
                        ));
            }
            assertTrue(labelBounds.getCenterX() < containerBounds.getCenterX(),
                    () -> describeTextInputLayoutGeometry(
                            containerBounds,
                            leadingBounds,
                            trailingBounds,
                            labelBounds,
                            supportingBounds,
                            counterBounds
                    ));
            assertTrue(supportingBounds.getCenterX() < counterBounds.getCenterX(),
                    () -> describeTextInputLayoutGeometry(
                            containerBounds,
                            leadingBounds,
                            trailingBounds,
                            labelBounds,
                            supportingBounds,
                            counterBounds
                    ));
            assertEquals(NodeOrientation.LEFT_TO_RIGHT, input.getEffectiveNodeOrientation());
        }

        assertEquals(Pos.TOP_LEFT, StackPane.getAlignment(label));
        assertTrue(outlineNotchGap(outline) >= labelBounds.getWidth() - 1.0,
                () -> "outlineNotchGap=" + outlineNotchGap(outline)
                        + ", labelBounds=" + labelBounds
                        + ", rightToLeft=" + rightToLeft);
    }

    /// Describes text input logical layout geometry for assertion failures.
    private static String describeTextInputLayoutGeometry(
            Bounds containerBounds,
            Bounds leadingBounds,
            Bounds trailingBounds,
            Bounds labelBounds,
            Bounds supportingBounds,
            Bounds counterBounds
    ) {
        return "containerBounds=" + containerBounds
                + ", leadingBounds=" + leadingBounds
                + ", trailingBounds=" + trailingBounds
                + ", labelBounds=" + labelBounds
                + ", supportingBounds=" + supportingBounds
                + ", counterBounds=" + counterBounds;
    }

    /// Returns whether a value is strictly inside the supplied range.
    private static boolean isBetweenExclusive(double value, double lowerBound, double upperBound) {
        return value > lowerBound && value < upperBound;
    }

    /// Returns the current top outline gap generated for a floating text input label.
    private static double outlineNotchGap(Path outline) {
        if (outline.getElements().size() < 3) {
            return 0.0;
        }
        var notchStart = assertInstanceOf(javafx.scene.shape.LineTo.class, outline.getElements().get(1));
        var notchEnd = assertInstanceOf(javafx.scene.shape.MoveTo.class, outline.getElements().get(2));
        return notchEnd.getX() - notchStart.getX();
    }

    /// Verifies that a value is between two exclusive bounds.
    private static void assertBetween(double actual, double lowerBound, double upperBound, String description) {
        assertTrue(actual > lowerBound && actual < upperBound,
                () -> description + ": actual=" + actual
                        + ", lowerBound=" + lowerBound
                        + ", upperBound=" + upperBound);
    }

    /// Verifies the resolved shape radius used by a control's state layer.
    private static void assertStateLayerShape(Node node, double expectedRadius) {
        Region overlay = lookupRegion(node, ".m3-state-layer");
        assertInstanceOf(Path.class, Objects.requireNonNull(overlay.getParent(), "clipped state content").getClip());
        assertStateLayerRadii(node, expectedRadius, expectedRadius, expectedRadius, expectedRadius);
    }

    /// Verifies the resolved corner radii used by a control's state layer.
    private static void assertStateLayerRadii(
            Node node,
            double topLeft,
            double topRight,
            double bottomRight,
            double bottomLeft
    ) {
        Region overlay = lookupRegion(node, ".m3-state-layer");
        Node clippedContent = Objects.requireNonNull(overlay.getParent(), "clipped state content");
        Path clip = assertInstanceOf(Path.class, clippedContent.getClip());
        assertPathRadii(clip, topLeft, topRight, bottomRight, bottomLeft);
    }

    /// Verifies which corners are rounded on a region's background.
    private static void assertRegionRoundedCorners(
            Region region,
            boolean topLeft,
            boolean topRight,
            boolean bottomRight,
            boolean bottomLeft
    ) {
        javafx.scene.layout.CornerRadii radii = region.getBackground().getFills().get(0).getRadii();
        assertEquals(topLeft, radii.getTopLeftHorizontalRadius() > 0.0);
        assertEquals(topRight, radii.getTopRightHorizontalRadius() > 0.0);
        assertEquals(bottomRight, radii.getBottomRightHorizontalRadius() > 0.0);
        assertEquals(bottomLeft, radii.getBottomLeftHorizontalRadius() > 0.0);
    }

    /// Verifies a region's concrete background corner radii.
    private static void assertRegionRadii(
            Region region,
            double topLeft,
            double topRight,
            double bottomRight,
            double bottomLeft
    ) {
        if (region.getShape() instanceof Path path && path.getElements().size() >= 9) {
            assertPathRadii(path, topLeft, topRight, bottomRight, bottomLeft);
            return;
        }

        javafx.scene.layout.CornerRadii radii = region.getBackground().getFills().get(0).getRadii();
        assertEquals(topLeft, radii.getTopLeftHorizontalRadius(), 0.0001);
        assertEquals(topLeft, radii.getTopLeftVerticalRadius(), 0.0001);
        assertEquals(topRight, radii.getTopRightHorizontalRadius(), 0.0001);
        assertEquals(topRight, radii.getTopRightVerticalRadius(), 0.0001);
        assertEquals(bottomRight, radii.getBottomRightHorizontalRadius(), 0.0001);
        assertEquals(bottomRight, radii.getBottomRightVerticalRadius(), 0.0001);
        assertEquals(bottomLeft, radii.getBottomLeftHorizontalRadius(), 0.0001);
        assertEquals(bottomLeft, radii.getBottomLeftVerticalRadius(), 0.0001);
    }

    /// Verifies the four corners represented by a reusable rounded-rectangle path.
    private static void assertPathRadii(
            Path path,
            double topLeft,
            double topRight,
            double bottomRight,
            double bottomLeft
    ) {
        assertEquals(topLeft, pathCornerRadius(path, 8), 0.0001);
        assertEquals(topRight, pathCornerRadius(path, 2), 0.0001);
        assertEquals(bottomRight, pathCornerRadius(path, 4), 0.0001);
        assertEquals(bottomLeft, pathCornerRadius(path, 6), 0.0001);
    }

    /// Returns one corner radius from a reusable rounded-rectangle path.
    private static double pathCornerRadius(Path path, int index) {
        PathElement element = path.getElements().get(index);
        return element instanceof javafx.scene.shape.ArcTo arc ? arc.getRadiusX() : 0.0;
    }

    /// Returns a shape looked up below a node.
    private static Shape lookupShape(Node node, String selector) {
        Node child = node.lookup(selector);
        assertInstanceOf(Shape.class, child);
        return (Shape) child;
    }

    /// Returns the primary progress bar track, excluding the secondary expressive track.
    private static Rectangle progressBarPrimaryTrack(M3ProgressBar progressBar) {
        for (Node node : progressBar.lookupAll(".track")) {
            if (node instanceof Rectangle rectangle
                    && !rectangle.getStyleClass().contains("m3-progress-bar-secondary-track")) {
                return rectangle;
            }
        }
        throw new AssertionError("Missing primary progress bar track below " + progressBar);
    }

    /// Returns whether the supplied path still uses the same sampled path elements.
    private static boolean pathElementsAreSame(Path path, List<PathElement> elements) {
        if (path.getElements().size() != elements.size()) {
            return false;
        }
        for (int i = 0; i < elements.size(); i++) {
            if (path.getElements().get(i) != elements.get(i)) {
                return false;
            }
        }
        return true;
    }

    /// Verifies that the supplied path still uses the same sampled path elements.
    private static void assertSamePathElements(Path path, List<PathElement> elements, String description) {
        assertEquals(elements.size(), path.getElements().size(), description + " path element count");
        for (int i = 0; i < elements.size(); i++) {
            assertSame(elements.get(i), path.getElements().get(i), description + " path element " + i);
        }
    }

    /// Returns whether animated expressive progress paths have advanced while keeping path elements stable.
    private static boolean expressiveProgressWavePathsMovedWithReusedElements(
            AtomicReference<@Nullable Pane> rootReference,
            AtomicReference<@Nullable M3ProgressBar> progressBarReference,
            AtomicReference<@Nullable M3ProgressIndicator> progressIndicatorReference,
            AtomicReference<@Nullable Path> barWaveReference,
            AtomicReference<@Nullable Path> circularTrackReference,
            AtomicReference<@Nullable Path> circularWaveReference,
            AtomicReference<@Nullable List<PathElement>> barElementsReference,
            AtomicReference<@Nullable List<PathElement>> circularTrackElementsReference,
            AtomicReference<@Nullable List<PathElement>> circularElementsReference,
            AtomicReference<@Nullable Point2D> initialBarPointReference,
            AtomicReference<@Nullable Point2D> initialCircularPointReference
    ) {
        @Nullable Pane root = rootReference.get();
        @Nullable M3ProgressBar progressBar = progressBarReference.get();
        @Nullable M3ProgressIndicator progressIndicator = progressIndicatorReference.get();
        @Nullable Path barWave = barWaveReference.get();
        @Nullable Path circularTrack = circularTrackReference.get();
        @Nullable Path circularWave = circularWaveReference.get();
        @Nullable List<PathElement> barElements = barElementsReference.get();
        @Nullable List<PathElement> circularTrackElements = circularTrackElementsReference.get();
        @Nullable List<PathElement> circularElements = circularElementsReference.get();
        @Nullable Point2D initialBarPoint = initialBarPointReference.get();
        @Nullable Point2D initialCircularPoint = initialCircularPointReference.get();
        if (root == null
                || progressBar == null
                || progressIndicator == null
                || barWave == null
                || circularTrack == null
                || circularWave == null
                || barElements == null
                || circularTrackElements == null
                || circularElements == null
                || initialBarPoint == null
                || initialCircularPoint == null) {
            return false;
        }

        root.applyCss();
        root.layout();
        progressBar.layout();
        progressIndicator.layout();
        return barWave.isVisible()
                && circularTrack.isVisible()
                && circularWave.isVisible()
                && pathElementsAreSame(barWave, barElements)
                && pathElementsAreSame(circularTrack, circularTrackElements)
                && pathElementsAreSame(circularWave, circularElements)
                && firstPathPoint(barWave).distance(initialBarPoint) > 0.1
                && firstPathPoint(circularWave).distance(initialCircularPoint) > 0.1;
    }

    /// Returns the first point in a path made from move, line, and cubic elements.
    private static Point2D firstPathPoint(Path path) {
        assertFalse(path.getElements().isEmpty());
        return pathElementPoint(path.getElements().get(0));
    }

    /// Returns the last point in a path made from move, line, and cubic elements.
    private static Point2D lastPathPoint(Path path) {
        assertFalse(path.getElements().isEmpty());
        return pathElementPoint(path.getElements().get(path.getElements().size() - 1));
    }

    /// Returns the point coordinates carried by a sampled path element.
    private static Point2D pathElementPoint(PathElement element) {
        if (element instanceof MoveTo moveTo) {
            return new Point2D(moveTo.getX(), moveTo.getY());
        }
        if (element instanceof LineTo lineTo) {
            return new Point2D(lineTo.getX(), lineTo.getY());
        }
        if (element instanceof CubicCurveTo cubicCurveTo) {
            return new Point2D(cubicCurveTo.getX(), cubicCurveTo.getY());
        }
        throw new AssertionError("Unsupported path element: " + element);
    }

    /// Verifies that selected radio dot pixels are visually centered inside the outer ring.
    private static void assertRadioButtonIndicatorRenderedCentersAligned(
            WritableImage image,
            M3RadioButton radioButton,
            String description
    ) {
        Shape ring = radioRing(radioButton);
        Shape dot = radioDot(radioButton);
        Point2D ringCenter = sceneCenter(ring);
        Point2D ringPixelCenter = contrastingPixelCentroid(image, ring, Color.WHITE, 0.08);
        Point2D dotPixelCenter = contrastingPixelCentroid(image, dot, Color.WHITE, 0.08);
        Rectangle2D dotPixelBounds = contrastingPixelBounds(image, dot, Color.WHITE, 0.08);

        assertEquals(ringCenter.getX(), ringPixelCenter.getX(), SELECTION_INDICATOR_RENDERED_CENTER_TOLERANCE,
                () -> description + " ring pixels are off-center: ringCenter="
                        + ringCenter + ", ringPixelCenter=" + ringPixelCenter);
        assertEquals(ringCenter.getY(), ringPixelCenter.getY(), SELECTION_INDICATOR_RENDERED_CENTER_TOLERANCE,
                () -> description + " ring pixels are off-center: ringCenter="
                        + ringCenter + ", ringPixelCenter=" + ringPixelCenter);
        assertEquals(ringPixelCenter.getX(), dotPixelCenter.getX(), SELECTION_INDICATOR_RENDERED_CENTER_TOLERANCE,
                () -> description + " dot pixels are not centered in the ring: ringPixelCenter="
                        + ringPixelCenter + ", dotPixelCenter=" + dotPixelCenter);
        assertEquals(ringPixelCenter.getY(), dotPixelCenter.getY(), SELECTION_INDICATOR_RENDERED_CENTER_TOLERANCE,
                () -> description + " dot pixels are not centered in the ring: ringPixelCenter="
                        + ringPixelCenter + ", dotPixelCenter=" + dotPixelCenter);
        assertEquals(dotPixelBounds.getWidth(), dotPixelBounds.getHeight(), 1.0,
                () -> description + " dot pixels are not circular: " + dotPixelBounds);
    }

