    /// Verifies that a popup scene root mirrors the expected owner theme style classes.
    private static void assertPopupRootUsesThemeClasses(Parent popupRoot, M3Theme theme) {
        assertTrue(popupRoot.getStyleClass().contains(M3ThemeManager.ROOT_STYLE_CLASS),
                () -> "popup root is missing " + M3ThemeManager.ROOT_STYLE_CLASS + ": " + popupRoot.getStyleClass());
        assertTrue(popupRoot.getStyleClass().contains(
                theme.profile() == M3Profile.EXPRESSIVE_2025
                        ? M3ThemeManager.EXPRESSIVE_PROFILE_STYLE_CLASS
                        : M3ThemeManager.BASELINE_PROFILE_STYLE_CLASS
        ), () -> "popup root is missing the expected profile class: " + popupRoot.getStyleClass());
        assertTrue(popupRoot.getStyleClass().contains(
                theme.brightness() == Brightness.DARK
                        ? M3ThemeManager.DARK_BRIGHTNESS_STYLE_CLASS
                        : M3ThemeManager.LIGHT_BRIGHTNESS_STYLE_CLASS
        ), () -> "popup root is missing the expected brightness class: " + popupRoot.getStyleClass());
    }

    /// Verifies a horizontal slider's rendered active and inactive segments around the handle gap.
    private static void assertHorizontalSliderSegments(M3Slider slider, boolean rightToLeft) {
        Region inactiveTrack = lookupRegion(slider, ".track");
        Region activeTrack = lookupRegion(slider, ".active-track");
        Region stopIndicator = lookupRegion(slider, ".stop-indicator");
        Region thumb = lookupRegion(slider, ".thumb");
        Bounds sliderBounds = slider.localToScene(slider.getBoundsInLocal());
        Bounds inactiveBounds = inactiveTrack.localToScene(inactiveTrack.getBoundsInLocal());
        Bounds activeBounds = activeTrack.localToScene(activeTrack.getBoundsInLocal());
        Bounds stopIndicatorBounds = stopIndicator.localToScene(stopIndicator.getBoundsInLocal());
        Bounds thumbBounds = thumb.localToScene(thumb.getBoundsInLocal());
        double trackStart = sliderBounds.getMinX() + slider.getThumbWidth() / 2.0;
        double trackEnd = sliderBounds.getMaxX() - slider.getThumbWidth() / 2.0;
        double trackLength = trackEnd - trackStart;
        double logicalPosition = normalizedSliderValue(slider);
        double visualPosition = rightToLeft ? 1.0 - logicalPosition : logicalPosition;
        double thumbCenter = trackStart + trackLength * visualPosition;
        double gapExtent = thumbBounds.getWidth() / 2.0 + slider.getThumbTrackGap();
        double leadingGapEdge = Math.max(trackStart, thumbCenter - gapExtent);
        double trailingGapEdge = Math.min(trackEnd, thumbCenter + gapExtent);

        assertEquals(thumbCenter, thumbBounds.getCenterX(), 0.0001);
        assertEquals(slider.getThumbWidth(), thumbBounds.getWidth(), 0.0001);
        if (rightToLeft) {
            assertEquals(trackStart, inactiveBounds.getMinX(), 0.0001);
            assertEquals(leadingGapEdge, inactiveBounds.getMaxX(), 0.0001);
            assertEquals(trailingGapEdge, activeBounds.getMinX(), 0.0001);
            assertEquals(trackEnd, activeBounds.getMaxX(), 0.0001);
        } else {
            assertEquals(trackStart, activeBounds.getMinX(), 0.0001);
            assertEquals(leadingGapEdge, activeBounds.getMaxX(), 0.0001);
            assertEquals(trailingGapEdge, inactiveBounds.getMinX(), 0.0001);
            assertEquals(trackEnd, inactiveBounds.getMaxX(), 0.0001);
        }
        double segmentGap = rightToLeft
                ? activeBounds.getMinX() - inactiveBounds.getMaxX()
                : inactiveBounds.getMinX() - activeBounds.getMaxX();
        assertEquals(thumbBounds.getWidth() + slider.getThumbTrackGap() * 2.0, segmentGap, 0.0001);
        double stopRadius = slider.getStopIndicatorSize() / 2.0;
        double expectedStopCenter = rightToLeft
                ? trackStart + slider.getStopIndicatorTrailingSpace() + stopRadius
                : trackEnd - slider.getStopIndicatorTrailingSpace() - stopRadius;
        assertTrue(stopIndicator.isVisible());
        assertEquals(expectedStopCenter, stopIndicatorBounds.getCenterX(), 0.0001);
        assertEquals(slider.getStopIndicatorSize(), stopIndicatorBounds.getWidth(), 0.0001);
        assertEquals(slider.getStopIndicatorSize(), stopIndicatorBounds.getHeight(), 0.0001);
    }

    /// Verifies a vertical slider's rendered active and inactive segments around the handle gap.
    private static void assertVerticalSliderSegments(M3Slider slider) {
        Region inactiveTrack = lookupRegion(slider, ".track");
        Region activeTrack = lookupRegion(slider, ".active-track");
        Region stopIndicator = lookupRegion(slider, ".stop-indicator");
        Region thumb = lookupRegion(slider, ".thumb");
        Bounds sliderBounds = slider.localToScene(slider.getBoundsInLocal());
        Bounds inactiveBounds = inactiveTrack.localToScene(inactiveTrack.getBoundsInLocal());
        Bounds activeBounds = activeTrack.localToScene(activeTrack.getBoundsInLocal());
        Bounds stopIndicatorBounds = stopIndicator.localToScene(stopIndicator.getBoundsInLocal());
        Bounds thumbBounds = thumb.localToScene(thumb.getBoundsInLocal());
        double trackStart = sliderBounds.getMinY() + slider.getThumbWidth() / 2.0;
        double trackEnd = sliderBounds.getMaxY() - slider.getThumbWidth() / 2.0;
        double trackLength = trackEnd - trackStart;
        double thumbCenter = trackEnd - trackLength * normalizedSliderValue(slider);
        double gapExtent = thumbBounds.getHeight() / 2.0 + slider.getThumbTrackGap();
        double upperGapEdge = Math.max(trackStart, thumbCenter - gapExtent);
        double lowerGapEdge = Math.min(trackEnd, thumbCenter + gapExtent);

        assertEquals(thumbCenter, thumbBounds.getCenterY(), 0.0001);
        assertEquals(slider.getThumbWidth(), thumbBounds.getHeight(), 0.0001);
        assertEquals(trackStart, inactiveBounds.getMinY(), 0.0001);
        assertEquals(upperGapEdge, inactiveBounds.getMaxY(), 0.0001);
        assertEquals(lowerGapEdge, activeBounds.getMinY(), 0.0001);
        assertEquals(trackEnd, activeBounds.getMaxY(), 0.0001);
        assertEquals(thumbBounds.getHeight() + slider.getThumbTrackGap() * 2.0,
                activeBounds.getMinY() - inactiveBounds.getMaxY(),
                0.0001);
        double stopRadius = slider.getStopIndicatorSize() / 2.0;
        assertTrue(stopIndicator.isVisible());
        assertEquals(
                trackStart + slider.getStopIndicatorTrailingSpace() + stopRadius,
                stopIndicatorBounds.getCenterY(),
                0.0001
        );
        assertEquals(slider.getStopIndicatorSize(), stopIndicatorBounds.getWidth(), 0.0001);
        assertEquals(slider.getStopIndicatorSize(), stopIndicatorBounds.getHeight(), 0.0001);
    }

    /// Verifies centered horizontal slider segments and end stops in rendered scene coordinates.
    private static void assertCenteredHorizontalSliderSegments(M3Slider slider, boolean rightToLeft) {
        List<Region> inactiveTracks = visibleSliderRegions(slider, ".track");
        List<Region> stopIndicators = visibleSliderRegions(slider, ".stop-indicator");
        inactiveTracks.sort((first, second) -> Double.compare(
                first.localToScene(first.getBoundsInLocal()).getMinX(),
                second.localToScene(second.getBoundsInLocal()).getMinX()
        ));
        stopIndicators.sort((first, second) -> Double.compare(
                first.localToScene(first.getBoundsInLocal()).getMinX(),
                second.localToScene(second.getBoundsInLocal()).getMinX()
        ));
        assertEquals(2, inactiveTracks.size());
        assertEquals(2, stopIndicators.size());

        Region activeTrack = lookupRegion(slider, ".active-track");
        Region thumb = lookupRegion(slider, ".thumb");
        Bounds sliderBounds = slider.localToScene(slider.getBoundsInLocal());
        Bounds leadingInactive = inactiveTracks.get(0).localToScene(inactiveTracks.get(0).getBoundsInLocal());
        Bounds trailingInactive = inactiveTracks.get(1).localToScene(inactiveTracks.get(1).getBoundsInLocal());
        Bounds activeBounds = activeTrack.localToScene(activeTrack.getBoundsInLocal());
        Bounds thumbBounds = thumb.localToScene(thumb.getBoundsInLocal());
        double trackStart = sliderBounds.getMinX() + slider.getThumbWidth() / 2.0;
        double trackEnd = sliderBounds.getMaxX() - slider.getThumbWidth() / 2.0;
        double trackCenter = (trackStart + trackEnd) / 2.0;
        double logicalPosition = normalizedSliderValue(slider);
        double visualPosition = rightToLeft ? 1.0 - logicalPosition : logicalPosition;
        double thumbCenter = trackStart + (trackEnd - trackStart) * visualPosition;
        double gapExtent = thumbBounds.getWidth() / 2.0 + slider.getThumbTrackGap();
        double activeStart = thumbCenter < trackCenter
                ? thumbCenter + gapExtent
                : trackCenter;
        double activeEnd = thumbCenter < trackCenter
                ? trackCenter
                : thumbCenter - gapExtent;

        assertEquals(thumbCenter, thumbBounds.getCenterX(), 0.0001);
        assertEquals(trackStart, leadingInactive.getMinX(), 0.0001);
        assertEquals(Math.min(trackCenter, thumbCenter - gapExtent),
                leadingInactive.getMaxX(), 0.0001);
        assertEquals(activeStart, activeBounds.getMinX(), 0.0001);
        assertEquals(activeEnd, activeBounds.getMaxX(), 0.0001);
        assertEquals(Math.max(trackCenter, thumbCenter + gapExtent),
                trailingInactive.getMinX(), 0.0001);
        assertEquals(trackEnd, trailingInactive.getMaxX(), 0.0001);
        assertRegionRadii(activeTrack, 0.0, 0.0, 0.0, 0.0);

        double stopRadius = slider.getStopIndicatorSize() / 2.0;
        double stopCenterOffset = slider.getStopIndicatorTrailingSpace() + stopRadius;
        Bounds leadingStop = stopIndicators.get(0).localToScene(stopIndicators.get(0).getBoundsInLocal());
        Bounds trailingStop = stopIndicators.get(1).localToScene(stopIndicators.get(1).getBoundsInLocal());
        assertEquals(trackStart + stopCenterOffset, leadingStop.getCenterX(), 0.0001);
        assertEquals(trackEnd - stopCenterOffset, trailingStop.getCenterX(), 0.0001);
    }

    /// Verifies centered vertical slider segments and end stops in rendered scene coordinates.
    private static void assertCenteredVerticalSliderSegments(M3Slider slider) {
        List<Region> inactiveTracks = visibleSliderRegions(slider, ".track");
        List<Region> stopIndicators = visibleSliderRegions(slider, ".stop-indicator");
        inactiveTracks.sort((first, second) -> Double.compare(
                first.localToScene(first.getBoundsInLocal()).getMinY(),
                second.localToScene(second.getBoundsInLocal()).getMinY()
        ));
        stopIndicators.sort((first, second) -> Double.compare(
                first.localToScene(first.getBoundsInLocal()).getMinY(),
                second.localToScene(second.getBoundsInLocal()).getMinY()
        ));
        assertEquals(2, inactiveTracks.size());
        assertEquals(2, stopIndicators.size());

        Region activeTrack = lookupRegion(slider, ".active-track");
        Region thumb = lookupRegion(slider, ".thumb");
        Bounds sliderBounds = slider.localToScene(slider.getBoundsInLocal());
        Bounds upperInactive = inactiveTracks.get(0).localToScene(inactiveTracks.get(0).getBoundsInLocal());
        Bounds lowerInactive = inactiveTracks.get(1).localToScene(inactiveTracks.get(1).getBoundsInLocal());
        Bounds activeBounds = activeTrack.localToScene(activeTrack.getBoundsInLocal());
        Bounds thumbBounds = thumb.localToScene(thumb.getBoundsInLocal());
        double trackStart = sliderBounds.getMinY() + slider.getThumbWidth() / 2.0;
        double trackEnd = sliderBounds.getMaxY() - slider.getThumbWidth() / 2.0;
        double trackCenter = (trackStart + trackEnd) / 2.0;
        double thumbCenter = trackEnd - (trackEnd - trackStart) * normalizedSliderValue(slider);
        double gapExtent = thumbBounds.getHeight() / 2.0 + slider.getThumbTrackGap();
        double activeStart = thumbCenter < trackCenter
                ? thumbCenter + gapExtent
                : trackCenter;
        double activeEnd = thumbCenter < trackCenter
                ? trackCenter
                : thumbCenter - gapExtent;

        assertEquals(thumbCenter, thumbBounds.getCenterY(), 0.0001);
        assertEquals(trackStart, upperInactive.getMinY(), 0.0001);
        assertEquals(Math.min(trackCenter, thumbCenter - gapExtent),
                upperInactive.getMaxY(), 0.0001);
        assertEquals(activeStart, activeBounds.getMinY(), 0.0001);
        assertEquals(activeEnd, activeBounds.getMaxY(), 0.0001);
        assertEquals(Math.max(trackCenter, thumbCenter + gapExtent),
                lowerInactive.getMinY(), 0.0001);
        assertEquals(trackEnd, lowerInactive.getMaxY(), 0.0001);

        double stopRadius = slider.getStopIndicatorSize() / 2.0;
        double stopCenterOffset = slider.getStopIndicatorTrailingSpace() + stopRadius;
        Bounds upperStop = stopIndicators.get(0).localToScene(stopIndicators.get(0).getBoundsInLocal());
        Bounds lowerStop = stopIndicators.get(1).localToScene(stopIndicators.get(1).getBoundsInLocal());
        assertEquals(trackStart + stopCenterOffset, upperStop.getCenterY(), 0.0001);
        assertEquals(trackEnd - stopCenterOffset, lowerStop.getCenterY(), 0.0001);
    }

    /// Returns visible slider regions matching a CSS selector.
    private static List<Region> visibleSliderRegions(M3Slider slider, String selector) {
        List<Region> regions = new ArrayList<>();
        for (Node node : slider.lookupAll(selector)) {
            if (node instanceof Region region && region.isVisible()) {
                regions.add(region);
            }
        }
        return regions;
    }

    /// Returns the slider value normalized to the supported range.
    private static double normalizedSliderValue(M3Slider slider) {
        double min = slider.getMin();
        double max = slider.getMax();
        if (max <= min) {
            return 0.0;
        }
        return Math.max(0.0, Math.min(1.0, (slider.getValue() - min) / (max - min)));
    }

    /// Verifies that vertical slider track segments use the caller-provided preferred height.
    private static void assertVerticalSliderTrackUsesExplicitHeight(M3Slider slider) {
        Region inactiveTrack = lookupRegion(slider, ".track");
        Region activeTrack = lookupRegion(slider, ".active-track");
        double coveredHeight = inactiveTrack.getBoundsInParent().getHeight()
                + activeTrack.getBoundsInParent().getHeight()
                + slider.getThumbWidth()
                + slider.getThumbTrackGap() * 2.0;
        assertTrue(coveredHeight >= 140.0, () -> "vertical slider track is too short: " + coveredHeight);
    }

    /// Verifies that rendered text nodes do not escape their nearest visual layout boundary.
    private static void assertRenderedTextNodesStayInsideLayout(Node root) {
        WritableImage image = snapshotImageOnFxThread(root);
        visitVisibleNodes(root, node -> {
            if (!(node instanceof Text text) || text.getText().isBlank() || !hasRenderableBounds(text)) {
                return;
            }

            Bounds textBounds = text.localToScene(text.getBoundsInLocal());
            Node boundary = nearestVisualBoundary(text, root);
            assertNodeInsideAncestor(boundary, text, 1.0);

            @Nullable Rectangle2D inkBounds = renderedTextInkBounds(image, text);
            if (inkBounds == null) {
                return;
            }

            assertRenderedTextInkHasVerticalRoom(text, textBounds, inkBounds);
            assertRectangleInsideNodeBounds(boundary, inkBounds, TEXT_INK_EDGE_TOLERANCE,
                    "rendered text ink leaves its nearest visual owner");
            assertRenderedTextInkHasExpectedHeight(text, textBounds, inkBounds);
        });
    }

    /// Verifies that rendered text ink does not materially overflow the text layout bounds.
    private static void assertRenderedTextInkHasVerticalRoom(
            Text text,
            Bounds textBounds,
            Rectangle2D inkBounds
    ) {
        double topRoom = inkBounds.getMinY() - textBounds.getMinY();
        double bottomRoom = textBounds.getMaxY() - inkBounds.getMaxY();
        assertTrue(topRoom >= -TEXT_INK_VERTICAL_OVERFLOW_TOLERANCE
                        && bottomRoom >= -TEXT_INK_VERTICAL_OVERFLOW_TOLERANCE,
                () -> "rendered text ink materially overflows its vertical layout edge: text="
                        + text.getText() + ", topRoom=" + topRoom + ", bottomRoom=" + bottomRoom
                        + ", textBounds=" + textBounds + ", inkBounds=" + inkBounds);
    }

    /// Verifies that rendered text ink keeps enough height to catch vertical clipping inside layout bounds.
    private static void assertRenderedTextInkHasExpectedHeight(
            Text text,
            Bounds textBounds,
            Rectangle2D inkBounds
    ) {
        if (!shouldCheckRenderedTextInkHeight(text)
                || inkBounds.getWidth() < Math.max(24.0, textBounds.getWidth() * 0.35)) {
            return;
        }

        double minimumInkHeight = Math.max(3.0, text.getFont().getSize() * TEXT_INK_MINIMUM_FONT_HEIGHT_RATIO);
        assertTrue(inkBounds.getHeight() + TEXT_INK_HEIGHT_CLIPPING_TOLERANCE >= minimumInkHeight,
                () -> "rendered text ink is too short for its font size and may be clipped: text="
                        + text.getText() + ", fontSize=" + text.getFont().getSize()
                        + ", minimumInkHeight=" + minimumInkHeight + ", inkBounds=" + inkBounds);
    }

    /// Returns whether a text node should participate in rendered-ink height clipping checks.
    private static boolean shouldCheckRenderedTextInkHeight(Text text) {
        if (text.getFont().getSize() < 6.0) {
            return false;
        }

        String value = text.getText();
        for (int index = 0; index < value.length(); index++) {
            if (Character.isLetterOrDigit(value.charAt(index))) {
                return true;
            }
        }
        return false;
    }

    /// Verifies that visual-gallery icon slots use vector graphics instead of text fallback glyphs.
    private static void assertVisualIconSlotsUseVectorGraphics(Node root) {
        visitVisibleNodes(root, node -> {
            if (node instanceof M3IconButton button) {
                assertIconSlotUsesVectorGraphic(button, button.getGraphic());
            } else if (node instanceof M3IconToggleButton button) {
                assertIconSlotUsesVectorGraphic(button, button.getGraphic());
            } else if (node instanceof M3FloatingActionButton button) {
                assertIconSlotUsesVectorGraphic(button, button.getGraphic());
            } else if (node instanceof M3NavigationItem item) {
                assertIconSlotUsesVectorGraphic(item, item.getGraphic());
            } else if (node instanceof M3Chip chip) {
                assertIconSlotUsesVectorGraphic(chip, chip.getGraphic());
            } else if (node instanceof M3TextInputLayout inputLayout) {
                assertIconSlotUsesVectorGraphic(inputLayout, inputLayout.getLeading());
            } else if (node instanceof M3ListItem item) {
                assertIconSlotUsesVectorGraphic(item, item.getLeading());
            }
        });
    }

    /// Verifies the resolved logical container alignment of composite controls.
    private static void assertCompositeControlContainerAlignment(
            M3CheckBox checkBox,
            M3RadioButton radioButton,
            M3Switch switchControl,
            M3SearchBar searchBar,
            M3SplitButton splitButton,
            Pos alignment,
            boolean rightToLeft
    ) {
        assertEquals(alignment, assertInstanceOf(
                HBox.class,
                checkBox.lookup(".m3-selection-container")
        ).getAlignment());
        assertEquals(alignment, assertInstanceOf(
                HBox.class,
                radioButton.lookup(".m3-selection-container")
        ).getAlignment());
        assertEquals(alignment, assertInstanceOf(
                HBox.class,
                switchControl.lookup(".m3-selection-container")
        ).getAlignment());
        assertEquals(alignment, assertInstanceOf(
                HBox.class,
                searchBar.lookup("." + M3SearchBar.CONTENT_STYLE_CLASS)
        ).getAlignment());
        M3Button actionButton = splitButtonActionButton(splitButton);
        M3MenuButton menuButton = splitButtonMenuButton(splitButton);
        Bounds actionBounds = actionButton.localToScene(actionButton.getLayoutBounds());
        Bounds menuBounds = menuButton.localToScene(menuButton.getLayoutBounds());
        double gap;
        if (rightToLeft) {
            assertTrue(actionBounds.getMinX() > menuBounds.getMinX());
            gap = actionBounds.getMinX() - menuBounds.getMaxX();
        } else {
            assertTrue(actionBounds.getMinX() < menuBounds.getMinX());
            gap = menuBounds.getMinX() - actionBounds.getMaxX();
        }
        assertEquals(splitButton.getSpacing(), gap, 1.0);
    }

    /// Verifies that the first child occupies a container's rendered logical start edge.
    private static void assertFirstChildAtLogicalStart(Region container, boolean rightToLeft) {
        Node firstChild = container.getChildrenUnmodifiable().get(0);
        Bounds containerBounds = container.localToScene(container.getBoundsInLocal());
        Bounds childBounds = firstChild.localToScene(firstChild.getBoundsInLocal());
        double expectedEdge = rightToLeft
                ? containerBounds.getMaxX() - container.getInsets().getLeft()
                : containerBounds.getMinX() + container.getInsets().getLeft();
        double actualEdge = rightToLeft ? childBounds.getMaxX() : childBounds.getMinX();

        assertEquals(expectedEdge, actualEdge, 1.0,
                () -> "containerBounds=" + containerBounds + ", childBounds=" + childBounds);
    }

    /// Verifies the physical left and right gaps around a rendered horizontal divider line.
    private static void assertHorizontalDividerPhysicalInsets(
            M3Divider divider,
            Region line,
            double expectedLeft,
            double expectedRight
    ) {
        Bounds dividerBounds = divider.localToScene(divider.getBoundsInLocal());
        Bounds lineBounds = line.localToScene(line.getBoundsInLocal());
        assertEquals(expectedLeft, lineBounds.getMinX() - dividerBounds.getMinX(), 1.0,
                () -> "dividerBounds=" + dividerBounds + ", lineBounds=" + lineBounds);
        assertEquals(expectedRight, dividerBounds.getMaxX() - lineBounds.getMaxX(), 1.0,
                () -> "dividerBounds=" + dividerBounds + ", lineBounds=" + lineBounds);
    }

    /// Returns the first descendant of the requested node type.
    ///
    /// @param root the root node to search
    /// @param type the descendant type to find
    /// @param <T>  the descendant node type
    /// @return the first matching descendant, including the root itself
    private static <T extends Node> T firstDescendantOfType(Node root, Class<T> type) {
        @Nullable T descendant = findFirstDescendantOfType(root, type);
        if (descendant != null) {
            return descendant;
        }
        throw new AssertionError("Expected descendant of type " + type.getSimpleName() + " under " + root);
    }

    /// Finds the first descendant of the requested node type.
    ///
    /// @param root the root node to search
    /// @param type the descendant type to find
    /// @param <T>  the descendant node type
    /// @return the first matching descendant, or `null` when none exists
    private static <T extends Node> @Nullable T findFirstDescendantOfType(Node root, Class<T> type) {
        if (type.isInstance(root)) {
            return type.cast(root);
        }
        if (root instanceof Parent parent) {
            for (Node child : parent.getChildrenUnmodifiable()) {
                @Nullable T descendant = findFirstDescendantOfType(child, type);
                if (descendant != null) {
                    return descendant;
                }
            }
        }
        return null;
    }

    /// Verifies that an icon slot graphic contains SVG geometry when present.
    private static void assertIconSlotUsesVectorGraphic(Node owner, @Nullable Node graphic) {
        if (graphic == null) {
            return;
        }

        assertTrue(
                containsSvgPath(graphic),
                () -> "visual icon slot should use SVG geometry: owner="
                        + owner.getClass().getSimpleName()
                        + ", graphic="
                        + graphic.getClass().getSimpleName()
        );
    }

    /// Returns whether a node hierarchy contains SVG path geometry.
    private static boolean containsSvgPath(Node node) {
        if (node instanceof SVGPath) {
            return true;
        }

        if (node instanceof Parent parent) {
            for (Node child : parent.getChildrenUnmodifiable()) {
                if (containsSvgPath(child)) {
                    return true;
                }
            }
        }

        return false;
    }

    /// Verifies that fixed Material touch targets keep their rendered content centered.
    private static void assertFixedTargetControlsKeepCenteredContent(Node root) {
        WritableImage image = snapshotImageOnFxThread(root);
        visitVisibleNodes(root, node -> {
            if (node instanceof M3IconButton button) {
                @Nullable Node graphic = button.getGraphic();
                if (graphic != null && (button.getText() == null || button.getText().isEmpty())) {
                    assertFixedTargetContentCentered(image, button, graphic, 1.0, 1.5);
                }
            } else if (node instanceof M3IconToggleButton button) {
                @Nullable Node graphic = button.getGraphic();
                if (graphic != null) {
                    assertFixedTargetContentCentered(image, button, graphic, 1.0, 1.5);
                }
            } else if (node instanceof M3FloatingActionButton button) {
                @Nullable Node graphic = button.getGraphic();
                if (graphic != null && (button.getText() == null || button.getText().isEmpty())) {
                    assertFixedTargetContentCentered(image, button, graphic, 1.0, 1.5);
                }
            } else if (node instanceof M3Tab tab) {
                @Nullable Node textNode = tab.lookup(".text");
                if (textNode != null && hasRenderableBounds(textNode)) {
                    assertFixedTargetContentVerticallyCentered(image, tab, textNode, 1.0, 2.0);
                }
            } else if (node instanceof M3SegmentedButton button) {
                @Nullable Node textNode = button.lookup(".text");
                if (textNode != null && hasRenderableBounds(textNode)) {
                    assertFixedTargetContentVerticallyCentered(image, button, textNode, 1.0, 2.0);
                }
            } else if (node instanceof ButtonBase button
                    && (button.getStyleClass().contains(M3DatePicker.DAY_CELL_STYLE_CLASS)
                    || button.getStyleClass().contains(M3TimePicker.CELL_STYLE_CLASS))) {
                @Nullable Node textNode = button.lookup(".text");
                if (textNode != null && hasRenderableBounds(textNode)) {
                    assertFixedTargetContentCentered(image, button, textNode, 1.0, 1.5);
                }
            }
        });
    }

    /// Verifies that navigation item graphic slots stay centered inside their indicator area.
    private static void assertNavigationItemsKeepGraphicContentCentered(Node root) {
        visitVisibleNodes(root, node -> {
            if (!(node instanceof M3NavigationItem item) || item.getGraphic() == null) {
                return;
            }

            @Nullable Node iconContainer = item.lookup(".m3-navigation-item-icon-container");
            @Nullable Node graphicContainer = item.lookup(".m3-navigation-item-graphic");
            if (iconContainer != null && graphicContainer != null && hasRenderableBounds(graphicContainer)) {
                assertNodeCentersAligned(iconContainer, graphicContainer, 1.0);
            }
        });
    }

    /// Verifies that both layout bounds and rendered ink stay centered in a fixed Material target.
    private static void assertFixedTargetContentCentered(
            WritableImage image,
            Node container,
            Node content,
            double layoutTolerance,
            double inkTolerance
    ) {
        assertNodeCentersAligned(container, content, layoutTolerance);
        @Nullable Text renderedText = firstRenderedText(content);
        if (renderedText == null || containsSvgPath(content)) {
            return;
        }

        Point2D containerCenter = sceneCenter(container);
        Rectangle2D inkBounds = requiredRenderedTextInkBounds(image, renderedText);
        double inkCenterX = inkBounds.getMinX() + inkBounds.getWidth() / 2.0;
        double inkCenterY = inkBounds.getMinY() + inkBounds.getHeight() / 2.0;
        assertEquals(containerCenter.getX(), inkCenterX, inkTolerance,
                () -> "fixed target rendered content is horizontally off-center: container="
                        + container + ", content=" + content + ", inkBounds=" + inkBounds);
        assertEquals(containerCenter.getY(), inkCenterY, inkTolerance,
                () -> "fixed target rendered content is vertically off-center: container="
                        + container + ", content=" + content + ", inkBounds=" + inkBounds);
    }

    /// Verifies that fixed-height target content keeps its layout and rendered ink vertically centered.
    private static void assertFixedTargetContentVerticallyCentered(
            WritableImage image,
            Node container,
            Node content,
            double layoutTolerance,
            double inkTolerance
    ) {
        assertNodeVerticalCentersAligned(container, content, layoutTolerance);
        @Nullable Text renderedText = firstRenderedText(content);
        if (renderedText == null || containsSvgPath(content)) {
            return;
        }

        Point2D containerCenter = sceneCenter(container);
        Rectangle2D inkBounds = requiredRenderedTextInkBounds(image, renderedText);
        double inkCenterY = inkBounds.getMinY() + inkBounds.getHeight() / 2.0;
        assertEquals(containerCenter.getY(), inkCenterY, inkTolerance,
                () -> "fixed target rendered content is vertically off-center: container="
                        + container + ", content=" + content + ", inkBounds=" + inkBounds);
    }

    /// Returns the first visible text node inside a rendered node subtree.
    private static @Nullable Text firstRenderedText(Node root) {
        if (root instanceof Text text && !text.getText().isBlank() && hasRenderableBounds(text)) {
            return text;
        }

        if (root instanceof Parent parent) {
            for (Node child : parent.getChildrenUnmodifiable()) {
                @Nullable Text text = firstRenderedText(child);
                if (text != null) {
                    return text;
                }
            }
        }

        return null;
    }

    /// Verifies that an already visible supporting row is not in an entry-transition frame.
    private static void assertVisibleSupportingRowIsStable(HBox supportingRow) {
        assertTrue(supportingRow.isVisible());
        assertTrue(supportingRow.isManaged());
        assertEquals(1.0, supportingRow.getOpacity(), 0.0001);
        assertEquals(0.0, supportingRow.getTranslateY(), 0.0001);
    }

    /// Verifies that single-line text inputs keep entered text ink in the active content slot.
    private static void assertSingleLineTextInputsKeepInkAligned(Node root) {
        WritableImage image = snapshotImageOnFxThread(root);
        visitVisibleNodes(root, node -> {
            if (!(node instanceof TextInputControl input)
                    || input instanceof M3TextArea
                    || !(input instanceof M3TextInput textInput)
                    || input.getText().isBlank()
                    || !hasRenderableBounds(input)) {
                return;
            }

            @Nullable Text text = firstRenderedText(input);
            assertTrue(text != null, () -> "single-line text input has no rendered text node: input=" + input);
            Text renderedText = Objects.requireNonNull(text);
            Bounds inputBounds = input.localToScene(input.getBoundsInLocal());
            Rectangle2D inkBounds = requiredRenderedTextInkBounds(image, renderedText);
            assertRectangleInsideNodeBounds(input, inkBounds, TEXT_INK_EDGE_TOLERANCE,
                    "single-line text input rendered ink leaves the editable field");
            Bounds textBounds = renderedText.localToScene(renderedText.getBoundsInLocal());
            double textCenterY = textBounds.getCenterY();
            @Nullable M3TextInputLayout layout = nearestTextInputLayout(input);
            if (layout != null) {
                assertTextInputInkAvoidsAdornmentSlot(
                        layout,
                        M3TextInputLayout.LEADING_STYLE_CLASS,
                        inkBounds,
                        "single-line text input leading adornment slot"
                );
                assertTextInputInkAvoidsAdornmentSlot(
                        layout,
                        M3TextInputLayout.TRAILING_STYLE_CLASS,
                        inkBounds,
                        "single-line text input trailing adornment slot"
                );
            }
            if (layout != null && layout.isLabelFloating() && textInput.getVariant() == M3TextInputVariant.FILLED) {
                double centerRatio = (textCenterY - inputBounds.getMinY()) / inputBounds.getHeight();
                assertTrue(centerRatio >= FILLED_FLOATING_INK_MINIMUM_CENTER_RATIO
                                && centerRatio <= FILLED_FLOATING_INK_MAXIMUM_CENTER_RATIO,
                        () -> "filled floating-label input rendered text ink is outside its content slot: input="
                                + inputBounds + ", text=" + textBounds + ", ink=" + inkBounds + ", centerRatio=" + centerRatio);
                return;
            }
            if (layout != null && layout.isLabelFloating() && textInput.getVariant() == M3TextInputVariant.OUTLINED) {
                double centerRatio = (textCenterY - inputBounds.getMinY()) / inputBounds.getHeight();
                assertTrue(centerRatio >= OUTLINED_FLOATING_INK_MINIMUM_CENTER_RATIO
                                && centerRatio <= OUTLINED_FLOATING_INK_MAXIMUM_CENTER_RATIO,
                        () -> "outlined floating-label input rendered text ink is outside its content slot: input="
                                + inputBounds + ", text=" + textBounds + ", ink=" + inkBounds + ", centerRatio=" + centerRatio);
                return;
            }

            double inputCenterY = (inputBounds.getMinY() + inputBounds.getMaxY()) / 2.0;
            assertEquals(inputCenterY, textCenterY, SINGLE_LINE_TEXT_INPUT_INK_CENTER_TOLERANCE,
                    () -> "single-line input rendered text ink is vertically misaligned: input="
                            + inputBounds + ", text=" + textBounds + ", ink=" + inkBounds + ", textInput=" + input);
        });
    }

    /// Verifies that visible text areas keep rendered text ink inside their multiline content region.
    private static void assertTextAreasKeepInkInsideContentArea(Node root) {
        WritableImage image = snapshotImageOnFxThread(root);
        visitVisibleNodes(root, node -> {
            if (node instanceof M3TextArea textArea && !textArea.getText().isBlank() && hasRenderableBounds(textArea)) {
                Region content = lookupRegion(textArea, ".content");
                assertTextAreaTextInkInsideContentArea(image, textArea, content, "visible text area");
            }
        });
    }

    /// Verifies that one text area's rendered text ink stays inside JavaFX's multiline content region.
    private static void assertTextAreaTextInkInsideContentArea(
            WritableImage image,
            M3TextArea textArea,
            Region content,
            String description
    ) {
        java.util.ArrayList<Rectangle2D> inkBoundsList = new java.util.ArrayList<>();
        visitVisibleNodes(textArea, node -> {
            if (!(node instanceof Text text) || text.getText().isBlank() || !hasRenderableBounds(text)) {
                return;
            }

            @Nullable Rectangle2D inkBounds = renderedTextInkBounds(image, text);
            if (inkBounds == null) {
                return;
            }

            Bounds textBounds = text.localToScene(text.getBoundsInLocal());
            assertRenderedTextInkHasVerticalRoom(text, textBounds, inkBounds);
            assertRenderedTextInkHasExpectedHeight(text, textBounds, inkBounds);
            assertRectangleInsideNodeBounds(
                    content,
                    inkBounds,
                    TEXT_AREA_CONTENT_INK_EDGE_TOLERANCE,
                    description + " rendered ink leaves the multiline content area"
            );
            inkBoundsList.add(inkBounds);
        });

        assertFalse(inkBoundsList.isEmpty(),
                () -> description + " has no rendered text ink: text=" + textArea.getText());
    }

    /// Verifies that rendered text ink does not overlap a visible Material adornment slot.
    private static void assertTextInputInkAvoidsAdornmentSlot(
            M3TextInputLayout layout,
            String slotStyleClass,
            Rectangle2D inkBounds,
            String description
    ) {
        @Nullable Node slot = layout.lookup("." + slotStyleClass);
        if (slot == null || !slot.isVisible() || !hasRenderableBounds(slot)) {
            return;
        }

        Bounds slotBounds = slot.localToScene(slot.getBoundsInLocal());
        double verticalOverlap = Math.min(inkBounds.getMaxY(), slotBounds.getMaxY())
                - Math.max(inkBounds.getMinY(), slotBounds.getMinY());
        if (verticalOverlap <= TEXT_INPUT_ADORNMENT_OVERLAP_TOLERANCE) {
            return;
        }

        double horizontalOverlap = Math.min(inkBounds.getMaxX(), slotBounds.getMaxX())
                - Math.max(inkBounds.getMinX(), slotBounds.getMinX());
        assertTrue(horizontalOverlap <= TEXT_INPUT_ADORNMENT_OVERLAP_TOLERANCE,
                () -> description + " overlaps rendered text ink: overlap=" + horizontalOverlap
                        + ", inkBounds=" + inkBounds + ", slotBounds=" + slotBounds
                        + ", input=" + textInputDebugState(layout.getInput()));
    }

    /// Returns diagnostic state for a text input layout input.
    private static String textInputDebugState(@Nullable TextInputControl input) {
        if (input == null) {
            return "null";
        }

        String alignment = input instanceof TextField textField ? String.valueOf(textField.getAlignment()) : "n/a";
        return input.getClass().getSimpleName()
                + "[text=" + input.getText()
                + ", nodeOrientation=" + input.getNodeOrientation()
                + ", effectiveNodeOrientation=" + input.getEffectiveNodeOrientation()
                + ", alignment=" + alignment
                + ", padding=" + input.getPadding() + "]";
    }

    /// Visits visible nodes in a rendered hierarchy.
    private static void visitVisibleNodes(Node node, Consumer<Node> visitor) {
        if (!node.isVisible()) {
            return;
        }

        visitor.accept(node);
        if (node instanceof Parent parent) {
            for (Node child : parent.getChildrenUnmodifiable()) {
                visitVisibleNodes(child, visitor);
            }
        }
    }

    /// Returns whether a node has non-empty rendered layout bounds.
    private static boolean hasRenderableBounds(Node node) {
        Bounds bounds = node.getLayoutBounds();
        return bounds.getWidth() > 0.5 && bounds.getHeight() > 0.5;
    }

    /// Returns the first visible rendered text node with the supplied text.
    private static Text renderedTextNode(Node root, String value) {
        AtomicReference<@Nullable Text> result = new AtomicReference<>();
        visitVisibleNodes(root, node -> {
            if (result.get() == null
                    && node instanceof Text text
                    && value.equals(text.getText())
                    && hasRenderableBounds(text)) {
                result.set(text);
            }
        });

        Text text = result.get();
        if (text == null) {
            throw new AssertionError("No rendered text node found for " + value);
        }
        return text;
    }

    /// Returns the nearest ancestor that should constrain visible text.
    private static Node nearestVisualBoundary(Node node, Node root) {
        @Nullable Parent parent = node.getParent();
        while (parent != null) {
            if (parent == root
                    || parent instanceof Region
                    || parent.getClip() != null) {
                return parent;
            }
            parent = parent.getParent();
        }
        return root;
    }

    /// Returns the nearest text input layout ancestor.
    private static @Nullable M3TextInputLayout nearestTextInputLayout(Node node) {
        @Nullable Parent parent = node.getParent();
        while (parent != null) {
            if (parent instanceof M3TextInputLayout layout) {
                return layout;
            }
            parent = parent.getParent();
        }
        return null;
    }

    /// Returns a date picker day cell for the supplied date.
    private static ButtonBase dateCellForDate(M3DatePicker picker, LocalDate date) {
        for (Node node : picker.lookupAll("." + M3DatePicker.DAY_CELL_STYLE_CLASS)) {
            if (node instanceof ButtonBase button && date.equals(button.getUserData())) {
                return button;
            }
        }
        throw new AssertionError("No date cell found for " + date);
    }

    /// Returns a time picker cell for the supplied time.
    private static ButtonBase timeCellForTime(M3TimePicker picker, LocalTime time) {
        for (Node node : picker.lookupAll("." + M3TimePicker.CELL_STYLE_CLASS)) {
            if (node instanceof ButtonBase button && time.equals(button.getUserData())) {
                return button;
            }
        }
        throw new AssertionError("No time cell found for " + time);
    }

    /// Verifies that a child node stays inside an ancestor boundary.
    private static void assertNodeInsideAncestor(Node ancestor, Node child, double tolerance) {
        Bounds ancestorBounds = ancestor.localToScene(ancestor.getLayoutBounds());
        Bounds childBounds = child.localToScene(child.getLayoutBounds());
        assertTrue(
                childBounds.getMinX() >= ancestorBounds.getMinX() - tolerance
                        && childBounds.getMaxX() <= ancestorBounds.getMaxX() + tolerance
                        && childBounds.getMinY() >= ancestorBounds.getMinY() - tolerance
                        && childBounds.getMaxY() <= ancestorBounds.getMaxY() + tolerance,
                () -> "child escaped visual boundary: child=" + child
                        + ", ancestor=" + ancestor
                        + ", childBounds=" + childBounds
                        + ", ancestorBounds=" + ancestorBounds
        );
    }

    /// Verifies that a rendered pixel rectangle is contained by a node in scene coordinates.
    private static void assertRectangleInsideNodeBounds(
            Node node,
            Rectangle2D rectangle,
            double tolerance,
            String description
    ) {
        Bounds nodeBounds = node.localToScene(node.getBoundsInLocal());
        assertTrue(rectangle.getMinX() >= nodeBounds.getMinX() - tolerance
                        && rectangle.getMaxX() <= nodeBounds.getMaxX() + tolerance
                        && rectangle.getMinY() >= nodeBounds.getMinY() - tolerance
                        && rectangle.getMaxY() <= nodeBounds.getMaxY() + tolerance,
                () -> description + ": node=" + node
                        + ", nodeBounds=" + nodeBounds
                        + ", rectangle=" + rectangle);
    }

    /// Verifies that a child node's visual center matches its container center.
    private static void assertNodeCentersAligned(Node container, Node child, double tolerance) {
        Point2D containerCenter = sceneCenter(container);
        Point2D childCenter = sceneCenter(child);
        Bounds containerBounds = container.localToScene(container.getLayoutBounds());
        Bounds childBounds = child.localToScene(child.getLayoutBounds());

        assertEquals(containerCenter.getX(), childCenter.getX(), tolerance,
                () -> "containerBounds=" + containerBounds + ", childBounds=" + childBounds);
        assertEquals(containerCenter.getY(), childCenter.getY(), tolerance,
                () -> "containerBounds=" + containerBounds + ", childBounds=" + childBounds);
    }

    /// Verifies that a child node's vertical visual center matches its container center.
    private static void assertNodeVerticalCentersAligned(Node container, Node child, double tolerance) {
        Point2D containerCenter = sceneCenter(container);
        Point2D childCenter = sceneCenter(child);
        Bounds containerBounds = container.localToScene(container.getLayoutBounds());
        Bounds childBounds = child.localToScene(child.getLayoutBounds());

        assertEquals(containerCenter.getY(), childCenter.getY(), tolerance,
                () -> "containerBounds=" + containerBounds + ", childBounds=" + childBounds);
    }

    /// Returns the scene-space center of a node's layout bounds.
    private static Point2D sceneCenter(Node node) {
        Bounds bounds = node.localToScene(node.getLayoutBounds());
        return new Point2D(
                (bounds.getMinX() + bounds.getMaxX()) / 2.0,
                (bounds.getMinY() + bounds.getMaxY()) / 2.0
        );
    }

    /// Verifies that a rendered child stays inside a rendered parent.
    private static void assertNodeInsideParent(Node parent, Node child) {
        Bounds parentBounds = parent.localToScene(parent.getBoundsInLocal());
        Bounds childBounds = child.localToScene(child.getBoundsInLocal());
        assertTrue(
                childBounds.getMinX() >= parentBounds.getMinX() - 0.0001
                        && childBounds.getMaxX() <= parentBounds.getMaxX() + 0.0001
                        && childBounds.getMinY() >= parentBounds.getMinY() - 0.0001
                        && childBounds.getMaxY() <= parentBounds.getMaxY() + 0.0001,
                () -> "childBounds=" + childBounds + ", parentBounds=" + parentBounds
        );
    }

    /// Verifies that a node user-agent stylesheet has the expected bundled suffix.
    private static void assertUserAgentStylesheet(Object node, String suffix) {
        try {
            Object stylesheet = node.getClass().getMethod("getUserAgentStylesheet").invoke(node);
            assertTrue(stylesheet instanceof String);
            assertTrue(((String) stylesheet).endsWith(suffix));
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    /// Returns a rendered pixel from a node snapshot.
    private static Color snapshotPixel(Node node, int x, int y) {
        return FxTestUtils.callOnFxThread(() -> snapshotImageOnFxThread(node).getPixelReader().getColor(x, y));
    }

    /// Verifies the aggregate accessibility state exposed for a binary toggle when supported by the runtime.
    private static void assertAggregateToggleState(Node control, boolean selected) {
        @Nullable AccessibleAttribute toggleStateAttribute = M3Accessible.attribute("TOGGLE_STATE");
        if (toggleStateAttribute == null) {
            assertNull(M3Accessible.toggleState(selected));
        } else {
            assertEquals(M3Accessible.toggleState(selected),
                    control.queryAccessibleAttribute(toggleStateAttribute));
        }
    }

    /// Verifies the aggregate accessibility state exposed for a three-state toggle when supported by the runtime.
    private static void assertAggregateToggleState(
            Node control,
            boolean selected,
            boolean indeterminate
    ) {
        @Nullable AccessibleAttribute toggleStateAttribute = M3Accessible.attribute("TOGGLE_STATE");
        if (toggleStateAttribute == null) {
            assertNull(M3Accessible.toggleState(selected, indeterminate));
        } else {
            assertEquals(M3Accessible.toggleState(selected, indeterminate),
                    control.queryAccessibleAttribute(toggleStateAttribute));
        }
    }

    /// Verifies that a control reports and focuses the expected accessibility focus node.
    private static void assertAccessibleFocus(Node control, Node expectedFocusNode) {
        assertSame(expectedFocusNode, control.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

        control.executeAccessibleAction(AccessibleAction.REQUEST_FOCUS);

        assertTrue(expectedFocusNode.isFocused());
    }

    /// Verifies that a container keeps the child that currently owns scene focus for default focus actions.
    private static void assertCurrentAccessibleFocus(Node control, Node focusedChild) {
        focusedChild.requestFocus();
        assertTrue(focusedChild.isFocused());
        assertSame(focusedChild, control.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));

        control.executeAccessibleAction(AccessibleAction.REQUEST_FOCUS);

        assertTrue(focusedChild.isFocused());

        control.executeAccessibleAction(AccessibleAction.SHOW_ITEM);

        assertTrue(focusedChild.isFocused());
        assertSame(focusedChild, control.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
    }

    /// Verifies that a parameterless show-item action focuses the expected accessibility item.
    private static void assertAccessibleShowItemFocus(Node outsideFocusNode, Node control, Node expectedFocusNode) {
        outsideFocusNode.requestFocus();
        assertTrue(outsideFocusNode.isFocused());

        control.executeAccessibleAction(AccessibleAction.SHOW_ITEM);

        assertTrue(expectedFocusNode.isFocused());
        assertSame(expectedFocusNode, control.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
    }

    /// Verifies that a structural owner exposes focus from a nested popup menu target.
    private static void assertNestedPopupAccessibleFocus(
            Node owner,
            M3MenuButton menuButton,
            M3SubMenuItem subMenuItem,
            M3MenuItem target
    ) {
        assertTrue(menuButton.isShowing());
        assertTrue(subMenuItem.isSubMenuShowing());
        assertTrue(target.isFocused());
        assertSame(target, menuButton.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
        assertSame(target, owner.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE));
    }

    /// Returns whether a virtualized list exposes a focused row with the supplied headline.
    private static boolean listViewFocusNodeHasHeadline(
            AtomicReference<@Nullable M3ListView<Integer>> listViewReference,
            String headline
    ) {
        @Nullable M3ListView<Integer> listView = listViewReference.get();
        if (listView == null) {
            return false;
        }

        @Nullable Object focusNode = listView.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE);
        return focusNode instanceof M3ListItem item && headline.equals(item.getHeadlineText());
    }

    /// Asserts that a virtualized list exposes a focused row with the supplied headline.
    private static void assertAccessibleListItemHeadline(M3ListView<?> listView, String headline) {
        M3ListItem item = assertInstanceOf(
                M3ListItem.class,
                listView.queryAccessibleAttribute(AccessibleAttribute.FOCUS_NODE)
        );
        assertEquals(headline, item.getHeadlineText());
    }

