    /// Returns a rendered pixel from a node-local coordinate in a root snapshot.
    private static Color snapshotNodePixel(WritableImage image, Node node, double x, double y) {
        var point = node.localToScene(x, y);
        int pixelX = clampPixelCoordinate((int) Math.round(point.getX()), (int) image.getWidth());
        int pixelY = clampPixelCoordinate((int) Math.round(point.getY()), (int) image.getHeight());
        return image.getPixelReader().getColor(pixelX, pixelY);
    }

    /// Verifies that a rendered region has rounded or square physical top edge corners.
    private static void assertSnapshotEdgeCorners(
            WritableImage image,
            Region region,
            boolean roundedLeft,
            boolean roundedRight
    ) {
        Color background = Color.WHITE;
        Bounds bounds = region.localToScene(region.getLayoutBounds());
        double topY = bounds.getMinY() + 2.0;
        double leftDistance = colorDistance(snapshotScenePixel(image, bounds.getMinX() + 2.0, topY), background);
        double rightDistance = colorDistance(snapshotScenePixel(image, bounds.getMaxX() - 3.0, topY), background);

        assertEquals(roundedLeft, leftDistance < 0.04,
                () -> "left corner distance=" + leftDistance + ", region=" + region);
        assertEquals(roundedRight, rightDistance < 0.04,
                () -> "right corner distance=" + rightDistance + ", region=" + region);
    }

    /// Verifies whether a region's top-right surface corner excludes its two-pixel inset sample.
    private static void assertRenderedTopRightCorner(
            Region region,
            WritableImage image,
            boolean excludesInset,
            Color background
    ) {
        Bounds bounds = region.localToScene(region.getLayoutBounds());
        Color sample = snapshotScenePixel(image, bounds.getMaxX() - 2.0, bounds.getMinY() + 2.0);
        double distance = colorDistance(sample, background);
        if (excludesInset) {
            assertTrue(distance < 0.05, () -> "expected rounded-away corner sample: distance=" + distance);
        } else {
            assertTrue(distance > 0.05, () -> "expected filled corner sample: distance=" + distance);
        }
    }

    /// Verifies whether a region's top-left surface corner excludes its two-pixel inset sample.
    private static void assertRenderedTopLeftCorner(
            Region region,
            WritableImage image,
            boolean excludesInset,
            Color background
    ) {
        Bounds bounds = region.localToScene(region.getLayoutBounds());
        Color sample = snapshotScenePixel(image, bounds.getMinX() + 2.0, bounds.getMinY() + 2.0);
        double distance = colorDistance(sample, background);
        if (excludesInset) {
            assertTrue(distance < 0.05, () -> "expected rounded-away corner sample: distance=" + distance);
        } else {
            assertTrue(distance > 0.05, () -> "expected filled corner sample: distance=" + distance);
        }
    }

    /// Returns a rendered pixel from a scene coordinate in a root snapshot.
    private static Color snapshotScenePixel(WritableImage image, double x, double y) {
        int pixelX = clampPixelCoordinate((int) Math.round(x), (int) image.getWidth());
        int pixelY = clampPixelCoordinate((int) Math.round(y), (int) image.getHeight());
        return image.getPixelReader().getColor(pixelX, pixelY);
    }

    /// Clamps a pixel coordinate to a rendered snapshot dimension.
    private static int clampPixelCoordinate(int coordinate, int dimension) {
        return Math.max(0, Math.min(dimension - 1, coordinate));
    }

    /// Returns a rendered image snapshot from a node on the FX thread.
    private static WritableImage snapshotImageOnFxThread(Node node) {
        WritableImage image = new WritableImage(
                (int) Math.ceil(node.getLayoutBounds().getWidth()),
                (int) Math.ceil(node.getLayoutBounds().getHeight())
        );
        node.snapshot(null, image);
        return image;
    }

    /// Resizes a region to its preferred size before taking a detached popup snapshot.
    private static void resizeToPreferredSize(Region region) {
        double width = Math.ceil(region.prefWidth(-1.0));
        double height = Math.ceil(region.prefHeight(width));
        region.resize(width, height);
        region.applyCss();
        region.layout();
    }

    /// Resizes a synthetic row to deterministic dimensions for keyboard page-step tests.
    private static void resizeRow(Region row) {
        row.resize(240.0, 40.0);
    }

    /// Returns the average color of a rendered snapshot area.
    private static Color averageSnapshotColor(WritableImage image, int minX, int minY, int maxX, int maxY) {
        int startX = clampPixelCoordinate(Math.min(minX, maxX), (int) image.getWidth());
        int startY = clampPixelCoordinate(Math.min(minY, maxY), (int) image.getHeight());
        int endX = clampPixelCoordinate(Math.max(minX, maxX), (int) image.getWidth());
        int endY = clampPixelCoordinate(Math.max(minY, maxY), (int) image.getHeight());
        double red = 0.0;
        double green = 0.0;
        double blue = 0.0;
        double opacity = 0.0;
        int count = 0;
        for (int y = startY; y <= endY; y++) {
            for (int x = startX; x <= endX; x++) {
                Color color = image.getPixelReader().getColor(x, y);
                red += color.getRed();
                green += color.getGreen();
                blue += color.getBlue();
                opacity += color.getOpacity();
                count++;
            }
        }
        assertTrue(count > 0, () -> "empty snapshot sample area: minX=" + minX
                + ", minY=" + minY + ", maxX=" + maxX + ", maxY=" + maxY);
        return new Color(red / count, green / count, blue / count, opacity / count);
    }

    /// Verifies that a rendered snapshot contains enough distinct visible colors.
    private static void assertSnapshotHasColorVariety(WritableImage image, int minimumColorCount) {
        Set<Integer> colors = new HashSet<>();
        for (int y = 0; y < image.getHeight(); y += 4) {
            for (int x = 0; x < image.getWidth(); x += 4) {
                int argb = image.getPixelReader().getArgb(x, y);
                if (((argb >>> 24) & 0xff) > 16) {
                    colors.add(argb & 0xf0f0f0f0);
                }
            }
        }

        assertTrue(colors.size() >= minimumColorCount,
                () -> "snapshotColorCount=" + colors.size() + ", minimum=" + minimumColorCount);
    }

    /// Verifies that a node's rendered bounds contain pixels that contrast with a reference color.
    private static void assertSnapshotNodeContainsContrast(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        var bounds = node.localToScene(node.getBoundsInLocal());
        assertSnapshotAreaContainsContrast(
                image,
                (int) Math.floor(bounds.getMinX()),
                (int) Math.floor(bounds.getMinY()),
                (int) Math.ceil(bounds.getMaxX()),
                (int) Math.ceil(bounds.getMaxY()),
                reference,
                minimumDistance,
                node.toString()
        );
    }

    /// Verifies that a node's own snapshot contains pixels that contrast with a reference color.
    private static void assertNodeSnapshotContainsContrast(Node node, Color reference, double minimumDistance) {
        WritableImage image = snapshotImageOnFxThread(node);
        assertSnapshotAreaContainsContrast(
                image,
                0,
                0,
                (int) image.getWidth(),
                (int) image.getHeight(),
                reference,
                minimumDistance,
                node + " snapshot"
        );
    }

    /// Verifies that a node's rendered border band contains pixels that contrast with a reference color.
    private static void assertSnapshotNodeBorderContainsContrast(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        var bounds = node.localToScene(node.getBoundsInLocal());
        int minX = (int) Math.floor(bounds.getMinX());
        int minY = (int) Math.floor(bounds.getMinY());
        int maxX = (int) Math.ceil(bounds.getMaxX());
        int maxY = (int) Math.ceil(bounds.getMaxY());
        String description = node + " border";

        if (snapshotAreaContainsContrast(image, minX, minY, maxX, minY + 3, reference, minimumDistance)
                || snapshotAreaContainsContrast(image, minX, maxY - 3, maxX, maxY, reference, minimumDistance)
                || snapshotAreaContainsContrast(image, minX, minY, minX + 3, maxY, reference, minimumDistance)
                || snapshotAreaContainsContrast(image, maxX - 3, minY, maxX, maxY, reference, minimumDistance)) {
            return;
        }

        throw new AssertionError("No contrasting border pixels found for " + description);
    }

    /// Verifies that a node snapshot keeps all contrasting pixels away from its rendered edges.
    private static void assertSnapshotNodeEdgesClear(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        var bounds = node.localToScene(node.getBoundsInLocal());
        int minX = (int) Math.floor(bounds.getMinX());
        int minY = (int) Math.floor(bounds.getMinY());
        int maxX = (int) Math.ceil(bounds.getMaxX());
        int maxY = (int) Math.ceil(bounds.getMaxY());
        int edge = Math.max(1, Math.min(3, Math.min(maxX - minX, maxY - minY) / 6));

        boolean touchesTop = snapshotAreaContainsContrast(image, minX, minY, maxX, minY + edge,
                reference, minimumDistance);
        boolean touchesBottom = snapshotAreaContainsContrast(image, minX, maxY - edge, maxX, maxY,
                reference, minimumDistance);
        boolean touchesLeft = snapshotAreaContainsContrast(image, minX, minY, minX + edge, maxY,
                reference, minimumDistance);
        boolean touchesRight = snapshotAreaContainsContrast(image, maxX - edge, minY, maxX, maxY,
                reference, minimumDistance);

        assertFalse(
                touchesTop || touchesBottom || touchesLeft || touchesRight,
                () -> "Contrasting pixels reached the edge for " + node + ", bounds=" + bounds
        );
    }

    /// Verifies that a snapshot area contains pixels that contrast with a reference color.
    private static void assertSnapshotAreaContainsContrast(
            WritableImage image,
            int minX,
            int minY,
            int maxX,
            int maxY,
            Color reference,
            double minimumDistance,
            String description
    ) {
        assertTrue(snapshotAreaContainsContrast(image, minX, minY, maxX, maxY, reference, minimumDistance),
                () -> "No contrasting pixels found for " + description);
    }

    /// Returns whether a snapshot area contains pixels that contrast with a reference color.
    private static boolean snapshotAreaContainsContrast(
            WritableImage image,
            int minX,
            int minY,
            int maxX,
            int maxY,
            Color reference,
            double minimumDistance
    ) {
        int startX = Math.max(0, minX);
        int startY = Math.max(0, minY);
        int endX = Math.min((int) image.getWidth(), maxX);
        int endY = Math.min((int) image.getHeight(), maxY);

        for (int y = startY; y < endY; y++) {
            for (int x = startX; x < endX; x++) {
                Color color = image.getPixelReader().getColor(x, y);
                if (color.getOpacity() > 0.1 && colorDistance(color, reference) >= minimumDistance) {
                    return true;
                }
            }
        }
        return false;
    }

    /// Returns the centroid of rendered pixels inside a node that contrast with the reference color.
    private static Point2D contrastingPixelCentroid(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        Bounds bounds = node.localToScene(node.getBoundsInLocal());
        int startX = Math.max(0, (int) Math.floor(bounds.getMinX()));
        int startY = Math.max(0, (int) Math.floor(bounds.getMinY()));
        int endX = Math.min((int) image.getWidth(), (int) Math.ceil(bounds.getMaxX()));
        int endY = Math.min((int) image.getHeight(), (int) Math.ceil(bounds.getMaxY()));
        double totalWeight = 0.0;
        double weightedX = 0.0;
        double weightedY = 0.0;

        for (int y = startY; y < endY; y++) {
            for (int x = startX; x < endX; x++) {
                Color color = image.getPixelReader().getColor(x, y);
                double distance = colorDistance(color, reference);
                if (color.getOpacity() > 0.1 && distance >= minimumDistance) {
                    double weight = color.getOpacity() * Math.min(1.0, distance);
                    totalWeight += weight;
                    weightedX += (x + 0.5) * weight;
                    weightedY += (y + 0.5) * weight;
                }
            }
        }

        assertTrue(totalWeight > 0.0, () -> "No contrasting pixels found for " + node);
        return new Point2D(weightedX / totalWeight, weightedY / totalWeight);
    }

    /// Returns the number of rendered pixels inside a node that contrast with the reference color.
    private static double contrastingPixelArea(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        Bounds bounds = node.localToScene(node.getBoundsInLocal());
        int startX = Math.max(0, (int) Math.floor(bounds.getMinX()));
        int startY = Math.max(0, (int) Math.floor(bounds.getMinY()));
        int endX = Math.min((int) image.getWidth(), (int) Math.ceil(bounds.getMaxX()));
        int endY = Math.min((int) image.getHeight(), (int) Math.ceil(bounds.getMaxY()));
        double area = 0.0;

        for (int y = startY; y < endY; y++) {
            for (int x = startX; x < endX; x++) {
                Color color = image.getPixelReader().getColor(x, y);
                double distance = colorDistance(color, reference);
                if (color.getOpacity() > 0.1 && distance >= minimumDistance) {
                    area += Math.min(1.0, color.getOpacity() * distance / minimumDistance);
                }
            }
        }

        assertTrue(area > 0.0, () -> "No contrasting pixels found for " + node);
        return area;
    }

    /// Returns a required rendered text ink bounds inside a snapshot.
    private static Rectangle2D requiredRenderedTextInkBounds(WritableImage image, Text text) {
        @Nullable Rectangle2D bounds = renderedTextInkBounds(image, text);
        assertTrue(bounds != null, () -> "No rendered text ink pixels found for " + text.getText());
        return Objects.requireNonNull(bounds);
    }

    /// Returns the rendered text ink bounds inside a snapshot, or `null` when pixel classification is inconclusive.
    private static @Nullable Rectangle2D renderedTextInkBounds(WritableImage image, Text text) {
        Paint fillPaint = text.getFill();
        if (fillPaint instanceof Color fill) {
            @Nullable Rectangle2D inkBounds = textFillPixelBounds(image, text, fill, null, 0.24);
            Color background = sampledTextBackgroundColor(image, text);
            inkBounds = unionRectangles(inkBounds, textFillPixelBounds(image, text, fill, background, 0.45));
            return unionRectangles(inkBounds, contrastingPixelBoundsOrNull(image, text, background, 0.04));
        }

        return contrastingPixelBoundsOrNull(image, text, sampledTextBackgroundColor(image, text), 0.04);
    }

    /// Returns the union of two nullable rectangle bounds.
    private static @Nullable Rectangle2D unionRectangles(
            @Nullable Rectangle2D first,
            @Nullable Rectangle2D second
    ) {
        if (first == null) {
            return second;
        }
        if (second == null) {
            return first;
        }

        double minX = Math.min(first.getMinX(), second.getMinX());
        double minY = Math.min(first.getMinY(), second.getMinY());
        double maxX = Math.max(first.getMaxX(), second.getMaxX());
        double maxY = Math.max(first.getMaxY(), second.getMaxY());
        return new Rectangle2D(minX, minY, maxX - minX, maxY - minY);
    }

    /// Returns pixel bounds for text pixels close to the requested fill color.
    private static @Nullable Rectangle2D textFillPixelBounds(
            WritableImage image,
            Text text,
            Color fill,
            @Nullable Color background,
            double maximumFillDistance
    ) {
        Bounds bounds = text.localToScene(text.getBoundsInLocal());
        int startX = Math.max(0, (int) Math.floor(bounds.getMinX()));
        int startY = Math.max(0, (int) Math.floor(bounds.getMinY()));
        int endX = Math.min((int) image.getWidth(), (int) Math.ceil(bounds.getMaxX()));
        int endY = Math.min((int) image.getHeight(), (int) Math.ceil(bounds.getMaxY()));
        int minX = endX;
        int minY = endY;
        int maxX = startX - 1;
        int maxY = startY - 1;

        for (int y = startY; y < endY; y++) {
            for (int x = startX; x < endX; x++) {
                Color color = image.getPixelReader().getColor(x, y);
                double fillDistance = colorDistance(color, fill);
                if (fillDistance > maximumFillDistance) {
                    continue;
                }
                if (background != null && fillDistance + 0.02 >= colorDistance(color, background)) {
                    continue;
                }

                minX = Math.min(minX, x);
                minY = Math.min(minY, y);
                maxX = Math.max(maxX, x);
                maxY = Math.max(maxY, y);
            }
        }

        if (maxX < minX || maxY < minY) {
            return null;
        }
        return new Rectangle2D(minX, minY, maxX - minX + 1.0, maxY - minY + 1.0);
    }

    /// Samples a nearby background pixel around a text node before measuring rendered text ink.
    private static Color sampledTextBackgroundColor(WritableImage image, Text text) {
        Bounds bounds = text.localToScene(text.getBoundsInLocal());
        int width = (int) image.getWidth();
        int height = (int) image.getHeight();
        int left = Math.max(0, (int) Math.floor(bounds.getMinX()) - 3);
        int right = Math.min(width - 1, (int) Math.ceil(bounds.getMaxX()) + 3);
        int top = Math.max(0, (int) Math.floor(bounds.getMinY()) - 3);
        int bottom = Math.min(height - 1, (int) Math.ceil(bounds.getMaxY()) + 3);
        @Nullable Color textFill = text.getFill() instanceof Color color ? color : null;
        @Nullable Color bestColor = null;
        double bestDistance = -1.0;

        for (int y = top; y <= bottom; y++) {
            for (int x = left; x <= right; x++) {
                if (x >= bounds.getMinX() && x <= bounds.getMaxX()
                        && y >= bounds.getMinY() && y <= bounds.getMaxY()) {
                    continue;
                }

                Color color = image.getPixelReader().getColor(x, y);
                if (textFill == null) {
                    return color;
                }

                double distance = colorDistance(color, textFill);
                if (distance > bestDistance) {
                    bestDistance = distance;
                    bestColor = color;
                }
            }
        }

        return bestColor == null ? sampledNodeBackgroundColor(image, text) : bestColor;
    }

    /// Returns the bounds of rendered pixels inside a node that contrast with its sampled local background.
    private static Color sampledNodeBackgroundColor(WritableImage image, Node node) {
        Bounds bounds = node.localToScene(node.getBoundsInLocal());
        int x = clampPixelCoordinate((int) Math.floor(bounds.getMinX()), (int) image.getWidth());
        int y = clampPixelCoordinate((int) Math.floor(bounds.getMinY()), (int) image.getHeight());
        return image.getPixelReader().getColor(x, y);
    }

    /// Returns the bounds of rendered pixels inside a node that contrast with the reference color.
    private static Rectangle2D contrastingPixelBounds(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        @Nullable Rectangle2D bounds = contrastingPixelBoundsOrNull(image, node, reference, minimumDistance);
        assertTrue(bounds != null, () -> "No contrasting pixels found for " + node);
        return Objects.requireNonNull(bounds);
    }

    /// Returns the rendered-pixel bounds inside a node that contrast with a reference color, or `null`.
    private static @Nullable Rectangle2D contrastingPixelBoundsOrNull(
            WritableImage image,
            Node node,
            Color reference,
            double minimumDistance
    ) {
        Bounds bounds = node.localToScene(node.getBoundsInLocal());
        int startX = Math.max(0, (int) Math.floor(bounds.getMinX()));
        int startY = Math.max(0, (int) Math.floor(bounds.getMinY()));
        int endX = Math.min((int) image.getWidth(), (int) Math.ceil(bounds.getMaxX()));
        int endY = Math.min((int) image.getHeight(), (int) Math.ceil(bounds.getMaxY()));
        int minX = endX;
        int minY = endY;
        int maxX = startX - 1;
        int maxY = startY - 1;

        for (int y = startY; y < endY; y++) {
            for (int x = startX; x < endX; x++) {
                Color color = image.getPixelReader().getColor(x, y);
                if (color.getOpacity() > 0.1 && colorDistance(color, reference) >= minimumDistance) {
                    minX = Math.min(minX, x);
                    minY = Math.min(minY, y);
                    maxX = Math.max(maxX, x);
                    maxY = Math.max(maxY, y);
                }
            }
        }

        if (maxX < minX || maxY < minY) {
            return null;
        }
        return new Rectangle2D(minX, minY, maxX - minX + 1.0, maxY - minY + 1.0);
    }

    /// Verifies that a node is an internal icon with the expected glyph.
    private static void assertInternalIcon(
            @Nullable Node node,
            M3InternalIcon.Glyph expectedGlyph,
            String description
    ) {
        M3InternalIcon icon = assertInstanceOf(
                M3InternalIcon.class,
                Objects.requireNonNull(node, description),
                description
        );
        assertEquals(expectedGlyph, icon.getGlyph(), description);
        assertFalse(icon.getPath().getContent().isBlank(), description);
        assertTrue(icon.getStyleClass().contains(M3InternalIcon.STYLE_CLASS), description);
        assertTrue(icon.getStyleClass().contains(internalIconColorRoleStyleClass(icon.getColorRole())), description);
        assertTrue(icon.getPath().getStyleClass().contains(M3InternalIcon.PATH_STYLE_CLASS), description);
        assertTrue(icon.getPath().getStyle().isBlank(), description);
    }

    /// Verifies that an internal icon has exactly the style class for its active color role.
    private static void assertInternalIconColorRole(M3InternalIcon icon, M3InternalIcon.ColorRole expectedRole) {
        assertEquals(expectedRole, icon.getColorRole());
        for (M3InternalIcon.ColorRole role : M3InternalIcon.ColorRole.values()) {
            String styleClass = internalIconColorRoleStyleClass(role);
            assertEquals(
                    role == expectedRole,
                    icon.getStyleClass().contains(styleClass),
                    () -> "Unexpected internal icon color role style class " + styleClass
                            + " for " + expectedRole
            );
        }
        assertTrue(icon.getPath().getStyle().isBlank(), "internal icon path should not use inline CSS");
    }

    /// Returns the public style class used by an internal icon color role.
    private static String internalIconColorRoleStyleClass(M3InternalIcon.ColorRole colorRole) {
        return switch (colorRole) {
            case PRIMARY -> M3InternalIcon.PRIMARY_STYLE_CLASS;
            case ON_PRIMARY -> M3InternalIcon.ON_PRIMARY_STYLE_CLASS;
            case ON_SECONDARY -> M3InternalIcon.ON_SECONDARY_STYLE_CLASS;
            case ON_TERTIARY -> M3InternalIcon.ON_TERTIARY_STYLE_CLASS;
            case ON_SURFACE -> M3InternalIcon.ON_SURFACE_STYLE_CLASS;
            case INVERSE_ON_SURFACE -> M3InternalIcon.INVERSE_ON_SURFACE_STYLE_CLASS;
            case ON_SURFACE_VARIANT -> M3InternalIcon.ON_SURFACE_VARIANT_STYLE_CLASS;
            case ON_PRIMARY_CONTAINER -> M3InternalIcon.ON_PRIMARY_CONTAINER_STYLE_CLASS;
        };
    }

    /// Verifies that a node is an icon button carrying the expected internal icon glyph.
    private static void assertInternalIconButton(
            @Nullable Node node,
            M3InternalIcon.Glyph expectedGlyph,
            String description
    ) {
        M3IconButton button = assertInstanceOf(
                M3IconButton.class,
                Objects.requireNonNull(node, description),
                description
        );
        assertInternalIcon(button.getGraphic(), expectedGlyph, description);
        assertTrue(button.getText().isEmpty(), description);
    }

    /// Verifies that a picker exposes both logical navigation chevrons.
    private static void assertNavigationGlyphs(Control picker) {
        Set<M3InternalIcon.Glyph> glyphs = new HashSet<>();
        for (Node node : picker.lookupAll("." + M3DatePicker.NAVIGATION_BUTTON_STYLE_CLASS)) {
            M3IconButton button = assertInstanceOf(M3IconButton.class, node);
            M3InternalIcon icon = assertInstanceOf(M3InternalIcon.class, button.getGraphic());
            glyphs.add(icon.getGlyph());
        }
        assertEquals(
                Set.of(M3InternalIcon.Glyph.CHEVRON_LEFT, M3InternalIcon.Glyph.CHEVRON_RIGHT),
                glyphs,
                () -> "Navigation glyphs for " + picker
        );
    }

    /// Writes a rendered snapshot to a build report path for manual visual inspection.
    private static void writeVisualSnapshot(WritableImage image, java.nio.file.Path path) {
        writeVisualSnapshot(toBufferedImage(image), path);
    }

    /// Writes a desktop image to a build report path for manual visual inspection.
    private static void writeVisualSnapshot(BufferedImage image, java.nio.file.Path path) {
        assertVisualSnapshotReportHasContent(image, path);
        try {
            java.nio.file.Path parent = path.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            ImageIO.write(image, "png", path.toFile());
            ControlVisualTestUtils.writeVisualSnapshotIndex(path);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /// Verifies that a visual report image is not empty or a single flat color.
    private static void assertVisualSnapshotReportHasContent(BufferedImage image, java.nio.file.Path path) {
        int width = image.getWidth();
        int height = image.getHeight();
        assertTrue(width > 0 && height > 0, () -> "visual snapshot has invalid dimensions: " + path);

        int visiblePixels = 0;
        int differentVisiblePixels = 0;
        int firstVisibleColor = 0;
        boolean hasFirstVisibleColor = false;
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int argb = image.getRGB(x, y);
                if (((argb >>> 24) & 0xff) <= 16) {
                    continue;
                }

                int colorBucket = argb & 0xf0f0f0f0;
                visiblePixels++;
                if (!hasFirstVisibleColor) {
                    firstVisibleColor = colorBucket;
                    hasFirstVisibleColor = true;
                } else if (colorBucket != firstVisibleColor) {
                    differentVisiblePixels++;
                }
            }
        }

        assertTrue(visiblePixels > 0, () -> "visual snapshot has no visible pixels: " + path);
        assertTrue(differentVisiblePixels > 0,
                () -> "visual snapshot is a single flat color and cannot prove rendered content: " + path);
    }

    /// Converts a JavaFX image snapshot to a desktop image for report output.
    private static BufferedImage toBufferedImage(WritableImage image) {
        int width = (int) image.getWidth();
        int height = (int) image.getHeight();
        BufferedImage bufferedImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                bufferedImage.setRGB(x, y, image.getPixelReader().getArgb(x, y));
            }
        }
        return bufferedImage;
    }

    /// Returns a simple RGB distance between two colors.
    private static double colorDistance(Color first, Color second) {
        return Math.abs(first.getRed() - second.getRed())
                + Math.abs(first.getGreen() - second.getGreen())
                + Math.abs(first.getBlue() - second.getBlue());
    }

    /// Verifies that a sampled snapshot pixel is close to the expected color.
    private static void assertColorNear(Color actual, Color expected, double maximumDistance, String description) {
        assertTrue(colorDistance(actual, expected) <= maximumDistance,
                () -> description + ": actual=" + actual + ", expected=" + expected);
    }

    /// Verifies that the lower content area of a text area uses the Material container background.
    private static void assertTextAreaContentBackgroundMatches(
            WritableImage image,
            Region content,
            Color expected,
            double maximumDistance,
            String description
    ) {
        Bounds bounds = content.localToScene(content.getBoundsInLocal());
        double minX = Math.max(0.0, bounds.getMinX() + 8.0);
        double maxX = Math.min(image.getWidth() - 1.0, bounds.getMaxX() - 8.0);
        double minY = Math.max(0.0, bounds.getMinY() + Math.max(24.0, bounds.getHeight() * 0.45));
        double maxY = Math.min(image.getHeight() - 1.0, bounds.getMaxY() - 8.0);

        assertTrue(minX <= maxX && minY <= maxY,
                () -> description + " has no sampleable content area: bounds=" + bounds);

        int mismatches = 0;
        int whiteLeaks = 0;
        int ignoredInkPixels = 0;
        double worstDistance = 0.0;
        Color worstColor = expected;
        int worstX = -1;
        int worstY = -1;

        for (int yIndex = 0; yIndex < 3; yIndex++) {
            double y = minY + (maxY - minY) * yIndex / 2.0;
            for (int xIndex = 0; xIndex < 5; xIndex++) {
                double x = minX + (maxX - minX) * xIndex / 4.0;
                int pixelX = (int) Math.round(x);
                int pixelY = (int) Math.round(y);
                Color color = image.getPixelReader().getColor(pixelX, pixelY);
                double distance = colorDistance(color, expected);
                if (distance > worstDistance) {
                    worstDistance = distance;
                    worstColor = color;
                    worstX = pixelX;
                    worstY = pixelY;
                }
                if (colorDistance(color, Color.WHITE) <= 0.02) {
                    whiteLeaks++;
                } else if (distance > maximumDistance) {
                    if (color.getBrightness() < 0.72) {
                        ignoredInkPixels++;
                    } else {
                        mismatches++;
                    }
                }
            }
        }

        String mismatchMessage = description + " sampled non-container pixels: mismatches=" + mismatches
                + ", worstColor=" + worstColor
                + ", ignoredInkPixels=" + ignoredInkPixels
                + ", worstDistance=" + worstDistance
                + ", worstPixel=(" + worstX + ", " + worstY + ")"
                + ", expected=" + expected
                + ", bounds=" + bounds;
        String whiteLeakMessage = description + " exposes JavaFX white content background: whiteLeaks=" + whiteLeaks
                + ", worstColor=" + worstColor
                + ", bounds=" + bounds;
        assertEquals(0, mismatches, mismatchMessage);
        assertEquals(0, whiteLeaks, whiteLeakMessage);
    }

    /// Returns whether the standalone control scene has reached a renderable fallback-styled state.
    private static boolean standaloneControlSceneReady(AtomicReference<@Nullable Stage> stageReference) {
        @Nullable Stage stage = stageReference.get();
        if (stage == null || !stage.isShowing() || stage.getScene() == null) {
            return false;
        }

        Parent root = stage.getScene().getRoot();
        root.applyCss();
        root.layout();
        return hasRenderableBounds(root);
    }

    /// Returns whether standalone tooltip popups have reached a renderable fallback-styled state.
    private static boolean standaloneTooltipPopupsReady(
            AtomicReference<@Nullable Stage> stageReference,
            AtomicReference<@Nullable M3Tooltip> plainTooltipReference,
            AtomicReference<@Nullable M3RichTooltip> richTooltipReference
    ) {
        @Nullable Stage stage = stageReference.get();
        @Nullable M3Tooltip plainTooltip = plainTooltipReference.get();
        @Nullable M3RichTooltip richTooltip = richTooltipReference.get();
        return stage != null
                && stage.isShowing()
                && stage.getScene() != null
                && tooltipPopupReady(plainTooltip, M3Tooltip.STYLE_CLASS)
                && tooltipPopupReady(richTooltip, M3RichTooltip.CONTAINER_STYLE_CLASS);
    }

    /// Returns whether a tooltip popup has visible styled content.
    private static boolean tooltipPopupReady(@Nullable M3Tooltip tooltip, String contentStyleClass) {
        if (tooltip == null || !tooltip.isShowing() || tooltip.getScene() == null || tooltip.getSkin() == null) {
            return false;
        }

        Node skinNode = tooltip.getSkin().getNode();
        skinNode.applyCss();
        if (skinNode instanceof Parent parent) {
            parent.layout();
            Node content = parent.lookup("." + contentStyleClass);
            return content != null && hasRenderableBounds(content);
        }
        return hasRenderableBounds(skinNode);
    }

    /// Asserts that a standalone tooltip popup has visible styled content.
    private static void assertStandaloneTooltipPopupReady(@Nullable M3Tooltip tooltip, String contentStyleClass) {
        assertTrue(tooltipPopupReady(tooltip, contentStyleClass), () -> "Tooltip popup did not render " + contentStyleClass);
    }

    /// Closes standalone tooltip popup test content.
    private static void closeStandaloneTooltipScene(
            AtomicReference<@Nullable Stage> stageReference,
            AtomicReference<@Nullable M3Tooltip> plainTooltipReference,
            AtomicReference<@Nullable M3RichTooltip> richTooltipReference
    ) {
        FxTestUtils.runOnFxThread(() -> {
            @Nullable M3Tooltip plainTooltip = plainTooltipReference.get();
            if (plainTooltip != null) {
                plainTooltip.hide();
            }
            @Nullable M3RichTooltip richTooltip = richTooltipReference.get();
            if (richTooltip != null) {
                richTooltip.hide();
            }
            @Nullable Stage stage = stageReference.get();
            if (stage != null) {
                stage.close();
            }
        });
    }

    /// Returns whether a picker control has completed CSS and skin creation after a popup presentation.
    private static boolean pickerControlReady(Control picker) {
        if (picker.getScene() == null) {
            return false;
        }
        picker.applyCss();
        picker.layout();
        return picker.getSkin() != null;
    }

    /// Returns whether a standalone internal icon has resolved a renderable fallback token fill.
    private static boolean standaloneInternalIconReady(
            AtomicReference<@Nullable Stage> stageReference,
            AtomicReference<@Nullable M3InternalIcon> iconReference
    ) {
        @Nullable Stage stage = stageReference.get();
        @Nullable M3InternalIcon icon = iconReference.get();
        if (stage == null || icon == null || !stage.isShowing() || stage.getScene() == null) {
            return false;
        }

        Parent root = stage.getScene().getRoot();
        root.applyCss();
        root.layout();
        return hasRenderableBounds(icon) && icon.getPath().getFill() != null;
    }

    /// Verifies one generic picker field popup reaches a renderable fallback-styled state in isolation.
    private static <T, P extends Control> void assertStandalonePickerPopupReady(
            M3PickerField<T, P> field
    ) throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<String> stateReference = new AtomicReference<>("owner stage not created");
        AtomicBoolean showRequested = new AtomicBoolean();
        P picker = field.getPicker();
        FxTestUtils.runOnFxThreadWhenStable(
                () -> {
                    @Nullable Stage stage = stageReference.get();
                    @Nullable Bounds screenBounds = field.localToScreen(field.getBoundsInLocal());
                    stateReference.set("stageShowing=" + (stage != null && stage.isShowing())
                            + ", screenBounds=" + screenBounds
                            + ", showRequested=" + showRequested.get()
                            + ", fieldShowing=" + field.isShowing()
                            + ", pickerScene=" + picker.getScene()
                            + ", pickerSkin=" + picker.getSkin());
                    if (stage == null || !stage.isShowing() || screenBounds == null) {
                        return false;
                    }
                    if (showRequested.compareAndSet(false, true)) {
                        field.showPicker();
                        return false;
                    }
                    return field.isShowing() && pickerControlReady(picker);
                },
                STANDALONE_FALLBACK_STYLE_STABLE_PULSES,
                stateReference::get,
                () -> stageReference.set(showStandalonePickerOwner(field)),
                () -> {
                    field.hidePicker();
                    @Nullable Stage stage = stageReference.get();
                    if (stage != null) {
                        stage.close();
                    }
                }
        );
    }

    /// Verifies one date-range picker popup reaches a renderable fallback-styled state in isolation.
    private static void assertStandalonePickerPopupReady(
            M3DateRangePickerField field
    ) throws InterruptedException {
        AtomicReference<@Nullable Stage> stageReference = new AtomicReference<>();
        AtomicReference<String> stateReference = new AtomicReference<>("owner stage not created");
        AtomicBoolean showRequested = new AtomicBoolean();
        M3DateRangePicker picker = field.getPicker();
        FxTestUtils.runOnFxThreadWhenStable(
                () -> {
                    @Nullable Stage stage = stageReference.get();
                    @Nullable Bounds screenBounds = field.localToScreen(field.getBoundsInLocal());
                    stateReference.set("stageShowing=" + (stage != null && stage.isShowing())
                            + ", screenBounds=" + screenBounds
                            + ", showRequested=" + showRequested.get()
                            + ", fieldShowing=" + field.isShowing()
                            + ", pickerScene=" + picker.getScene()
                            + ", pickerSkin=" + picker.getSkin());
                    if (stage == null || !stage.isShowing() || screenBounds == null) {
                        return false;
                    }
                    if (showRequested.compareAndSet(false, true)) {
                        field.showPicker();
                        return false;
                    }
                    return field.isShowing() && pickerControlReady(picker);
                },
                STANDALONE_FALLBACK_STYLE_STABLE_PULSES,
                stateReference::get,
                () -> stageReference.set(showStandalonePickerOwner(field)),
                () -> {
                    field.hidePicker();
                    @Nullable Stage stage = stageReference.get();
                    if (stage != null) {
                        stage.close();
                    }
                }
        );
    }

    /// Creates and shows a standalone owner window for one picker field.
    private static Stage showStandalonePickerOwner(Control field) {
        VBox root = new VBox(field);
        Stage stage = new Stage();
        stage.setScene(new Scene(root, 560.0, 360.0));
        stage.show();
        root.applyCss();
        root.layout();
        return stage;
    }

    /// Verifies that token updates do not overwrite application-bound Region layout properties.
    private static void assertBoundRegionMetricsPreserved(Region region, Runnable tokenUpdate, Runnable tokenAssertions) {
        SimpleDoubleProperty minWidth = new SimpleDoubleProperty(31.0);
        SimpleDoubleProperty prefWidth = new SimpleDoubleProperty(41.0);
        SimpleDoubleProperty maxWidth = new SimpleDoubleProperty(91.0);
        SimpleDoubleProperty minHeight = new SimpleDoubleProperty(32.0);
        SimpleDoubleProperty prefHeight = new SimpleDoubleProperty(42.0);
        SimpleDoubleProperty maxHeight = new SimpleDoubleProperty(92.0);
        SimpleObjectProperty<Insets> padding = new SimpleObjectProperty<>(new Insets(1.0, 2.0, 3.0, 4.0));
        region.minWidthProperty().bind(minWidth);
        region.prefWidthProperty().bind(prefWidth);
        region.maxWidthProperty().bind(maxWidth);
        region.minHeightProperty().bind(minHeight);
        region.prefHeightProperty().bind(prefHeight);
        region.maxHeightProperty().bind(maxHeight);
        region.paddingProperty().bind(padding);

        try {
            tokenUpdate.run();
            tokenAssertions.run();

            assertEquals(31.0, region.getMinWidth(), 0.0001);
            assertEquals(41.0, region.getPrefWidth(), 0.0001);
            assertEquals(91.0, region.getMaxWidth(), 0.0001);
            assertEquals(32.0, region.getMinHeight(), 0.0001);
            assertEquals(42.0, region.getPrefHeight(), 0.0001);
            assertEquals(92.0, region.getMaxHeight(), 0.0001);
            assertEquals(new Insets(1.0, 2.0, 3.0, 4.0), region.getPadding());

            minWidth.set(35.0);
            prefWidth.set(45.0);
            maxWidth.set(95.0);
            minHeight.set(36.0);
            prefHeight.set(46.0);
            maxHeight.set(96.0);
            padding.set(new Insets(5.0, 6.0, 7.0, 8.0));

            assertEquals(35.0, region.getMinWidth(), 0.0001);
            assertEquals(45.0, region.getPrefWidth(), 0.0001);
            assertEquals(95.0, region.getMaxWidth(), 0.0001);
            assertEquals(36.0, region.getMinHeight(), 0.0001);
            assertEquals(46.0, region.getPrefHeight(), 0.0001);
            assertEquals(96.0, region.getMaxHeight(), 0.0001);
            assertEquals(new Insets(5.0, 6.0, 7.0, 8.0), region.getPadding());
        } finally {
            region.minWidthProperty().unbind();
            region.prefWidthProperty().unbind();
            region.maxWidthProperty().unbind();
            region.minHeightProperty().unbind();
            region.prefHeightProperty().unbind();
            region.maxHeightProperty().unbind();
            region.paddingProperty().unbind();
        }
    }

    /// Verifies one Region control against generated theme CSS layout metrics.
    private static void assertGeneratedThemeCssPreservesBoundRegionMetrics(Region region) {
        Pane root = new Pane(region);
        Scene scene = new Scene(root);

        assertBoundRegionMetricsPreserved(region, () -> {
            M3ThemeManager.install(scene, M3Theme.defaultTheme());
            root.applyCss();
            M3ThemeManager.install(scene, M3Theme.fromSeed(
                    Color.web("#006a6a"),
                    M3Profile.EXPRESSIVE_2025,
                    Brightness.LIGHT
            ));
            root.applyCss();
        }, () -> assertSame(scene, region.getScene()));
    }

