    /// Verifies that one button-like control fires from a pointer click near its layout edge.
    private static void assertButtonBaseFullBoundsClick(ButtonBase control, String description) {
        AtomicInteger fireCount = new AtomicInteger();
        control.setOnAction(event -> fireCount.incrementAndGet());
        Pane root = new Pane(control);
        Scene scene = new Scene(root, 240.0, 120.0);

        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        root.applyCss();
        control.resize(180.0, Math.max(56.0, control.prefHeight(180.0)));
        control.layout();

        double x = Math.max(1.0, control.getLayoutBounds().getWidth() - 2.0);
        double y = Math.max(1.0, control.getLayoutBounds().getHeight() - 2.0);
        assertTrue(control.isPickOnBounds(), () -> description + " should pick on full layout bounds");
        assertTrue(control.contains(x, y),
                () -> description + " should contain a pointer near the layout edge: x=" + x + ", y=" + y);

        control.fireEvent(primaryMouseEvent(control, MouseEvent.MOUSE_PRESSED, x, y, true));
        assertTrue(control.isArmed(), () -> description + " should arm from a full-bounds pointer press");
        control.fireEvent(primaryMouseEvent(control, MouseEvent.MOUSE_RELEASED, x, y, false));

        assertFalse(control.isArmed(), () -> description + " should disarm after pointer release");
        assertEquals(1, fireCount.get(), () -> description + " should fire from a full-bounds pointer click");
    }

    /// Verifies that one child of a grouped action control fires from a pointer click near its layout edge.
    private static void assertGroupedButtonBaseFullBoundsClick(
            Control group,
            ButtonBase control,
            String description
    ) {
        AtomicInteger fireCount = new AtomicInteger();
        control.setOnAction(event -> fireCount.incrementAndGet());
        Pane root = new Pane(group);
        Scene scene = new Scene(root, 420.0, 140.0);

        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        root.applyCss();

        double width = Math.max(240.0, Math.ceil(group.prefWidth(-1.0)));
        double height = Math.max(72.0, Math.ceil(group.prefHeight(width)));
        group.resizeRelocate(20.0, 20.0, width, height);
        root.layout();
        group.layout();
        control.layout();

        double x = Math.max(1.0, control.getLayoutBounds().getWidth() - 2.0);
        double y = Math.max(1.0, control.getLayoutBounds().getHeight() / 2.0);
        assertTrue(control.isPickOnBounds(), () -> description + " should pick on full layout bounds");
        assertTrue(control.contains(x, y),
                () -> description + " should contain a pointer near the layout edge: x=" + x + ", y=" + y);

        control.fireEvent(primaryMouseEvent(control, MouseEvent.MOUSE_PRESSED, x, y, true));
        assertTrue(control.isArmed(), () -> description + " should arm from a grouped full-bounds pointer press");
        control.fireEvent(primaryMouseEvent(control, MouseEvent.MOUSE_RELEASED, x, y, false));

        assertFalse(control.isArmed(), () -> description + " should disarm after pointer release");
        assertEquals(1, fireCount.get(), () -> description + " should fire from a grouped full-bounds pointer click");
    }

    /// Verifies that one list item fires from a pointer click near its layout edge.
    private static void assertListItemFullBoundsClick(M3ListItem item) {
        AtomicInteger fireCount = new AtomicInteger();
        item.setOnAction(event -> fireCount.incrementAndGet());
        Pane root = new Pane(item);
        Scene scene = new Scene(root, 280.0, 120.0);

        M3ThemeManager.install(scene, M3Theme.defaultTheme());
        root.applyCss();
        item.resize(240.0, 64.0);
        item.layout();

        double x = item.getLayoutBounds().getWidth() - 2.0;
        double y = item.getLayoutBounds().getHeight() - 2.0;
        assertTrue(item.isPickOnBounds(), "M3ListItem should pick on full layout bounds");
        assertTrue(item.contains(x, y),
                () -> "M3ListItem should contain a pointer near the layout edge: x=" + x + ", y=" + y);

        item.fireEvent(primaryMouseEvent(item, MouseEvent.MOUSE_PRESSED, x, y, true));
        item.fireEvent(primaryMouseEvent(item, MouseEvent.MOUSE_RELEASED, x, y, false));

        assertEquals(1, fireCount.get(), "M3ListItem should fire from a full-bounds pointer click");
    }

    /// Resizes a button group to its preferred dimensions and lays out its skin container and children.
    private static void resizeButtonGroupToPreferredSize(M3ButtonGroup group) {
        group.resize(group.prefWidth(-1.0), group.prefHeight(-1.0));
        group.layout();
    }

    /// Fires one complete synthetic primary-button click at the center of a node.
    private static void firePrimaryClick(Node node) {
        Bounds bounds = node.getLayoutBounds();
        double x = bounds.getMinX() + bounds.getWidth() / 2.0;
        double y = bounds.getMinY() + bounds.getHeight() / 2.0;
        node.fireEvent(primaryMouseEvent(node, MouseEvent.MOUSE_PRESSED, x, y, true));
        node.fireEvent(primaryMouseEvent(node, MouseEvent.MOUSE_RELEASED, x, y, false));
        node.fireEvent(primaryMouseEvent(node, MouseEvent.MOUSE_CLICKED, x, y, false));
    }

    /// Returns whether a tooltip popup overlaps one owner rectangle in screen coordinates.
    private static boolean popupOverlaps(M3Tooltip tooltip, Bounds ownerBounds) {
        double popupMinX = tooltip.getX();
        double popupMinY = tooltip.getY();
        double popupMaxX = popupMinX + tooltip.getWidth();
        double popupMaxY = popupMinY + tooltip.getHeight();
        return popupMaxX > ownerBounds.getMinX()
                && popupMinX < ownerBounds.getMaxX()
                && popupMaxY > ownerBounds.getMinY()
                && popupMinY < ownerBounds.getMaxY();
    }

    /// Creates a primary mouse event for control behavior tests.
    private static MouseEvent primaryMouseEvent(
            EventType<MouseEvent> eventType,
            double x,
            double y,
            boolean primaryButtonDown
    ) {
        return new MouseEvent(
                eventType,
                x,
                y,
                x,
                y,
                MouseButton.PRIMARY,
                1,
                false,
                false,
                false,
                false,
                primaryButtonDown,
                false,
                false,
                false,
                false,
                false,
                null
        );
    }

    /// Creates a primary mouse event at one local point of a concrete node.
    private static MouseEvent primaryMouseEvent(
            Node node,
            EventType<MouseEvent> eventType,
            double x,
            double y,
            boolean primaryButtonDown
    ) {
        Point2D scenePoint = node.localToScene(x, y);
        Point2D screenPoint = node.localToScreen(x, y);
        double screenX = screenPoint == null ? scenePoint.getX() : screenPoint.getX();
        double screenY = screenPoint == null ? scenePoint.getY() : screenPoint.getY();
        return new MouseEvent(
                eventType,
                scenePoint.getX(),
                scenePoint.getY(),
                screenX,
                screenY,
                MouseButton.PRIMARY,
                1,
                false,
                false,
                false,
                false,
                primaryButtonDown,
                false,
                false,
                false,
                false,
                false,
                new PickResult(node, scenePoint.getX(), scenePoint.getY())
        );
    }

    /// Creates a primary mouse event at one point expressed in scene coordinates.
    private static MouseEvent primaryMouseEventAtScenePoint(
            Node node,
            EventType<MouseEvent> eventType,
            double sceneX,
            double sceneY,
            boolean primaryButtonDown
    ) {
        Point2D localPoint = node.sceneToLocal(sceneX, sceneY);
        return primaryMouseEvent(node, eventType, localPoint.getX(), localPoint.getY(), primaryButtonDown);
    }

    /// Creates an indirect scroll event for scroll behavior tests.
    private static ScrollEvent scrollEvent(Node target, double deltaX, double deltaY) {
        return scrollEvent(target, deltaX, deltaY, false);
    }

    /// Returns the expected normalized position after a virtualized list wheel-scroll delta.
    private static double expectedListViewWheelTargetPosition(
            M3ListView<?> listView,
            VirtualFlow<?> flow,
            double deltaY
    ) {
        double rowHeight = listView.getFixedCellSize();
        assertTrue(rowHeight > 0.0, () -> "fixedCellSize=" + rowHeight);
        double viewportHeight = flow.getHeight() > 0.0 ? flow.getHeight() : listView.getHeight();
        double scrollablePixels = Math.max(0.0, rowHeight * listView.getItems().size() - viewportHeight);
        assertTrue(scrollablePixels > 0.0, () -> "scrollablePixels=" + scrollablePixels);
        return clampToUnit(flow.getPosition() - deltaY / scrollablePixels);
    }

    /// Returns a value clamped to the unit interval.
    private static double clampToUnit(double value) {
        return clamp(value, 0.0, 1.0);
    }

    /// Returns a value clamped into a closed range.
    private static double clamp(double value, double minValue, double maxValue) {
        if (value <= minValue) {
            return minValue;
        }
        return Math.min(value, maxValue);
    }

    /// Creates a scroll event for scroll behavior tests.
    private static ScrollEvent scrollEvent(Node target, double deltaX, double deltaY, boolean direct) {
        return scrollEvent(target, deltaX, deltaY, direct, false);
    }

    /// Creates a scroll event for scroll behavior tests.
    private static ScrollEvent scrollEvent(
            Node target,
            double deltaX,
            double deltaY,
            boolean direct,
            boolean shiftDown
    ) {
        return scrollEvent(
                target,
                deltaX,
                deltaY,
                direct,
                shiftDown,
                ScrollEvent.HorizontalTextScrollUnits.NONE,
                0.0,
                ScrollEvent.VerticalTextScrollUnits.NONE,
                0.0
        );
    }

    /// Creates a scroll event with explicit platform text-scroll units for scroll behavior tests.
    private static ScrollEvent scrollEvent(
            Node target,
            double deltaX,
            double deltaY,
            boolean direct,
            boolean shiftDown,
            ScrollEvent.HorizontalTextScrollUnits horizontalUnits,
            double textDeltaX,
            ScrollEvent.VerticalTextScrollUnits verticalUnits,
            double textDeltaY
    ) {
        return new ScrollEvent(
                target,
                target,
                ScrollEvent.SCROLL,
                40.0,
                40.0,
                40.0,
                40.0,
                shiftDown,
                false,
                false,
                false,
                direct,
                false,
                deltaX,
                deltaY,
                deltaX,
                deltaY,
                horizontalUnits,
                textDeltaX,
                verticalUnits,
                textDeltaY,
                0,
                null
        );
    }

    /// Asserts that container-level navigation does not move focus out of an embedded text input.
    private static void assertContainerNavigationDoesNotStealTextInputFocus(
            Parent root,
            Node navigationOwner,
            TextInputControl editor,
            Node adjacentTarget,
            KeyCode keyCode
    ) {
        root.applyCss();
        root.layout();
        editor.requestFocus();
        assertTrue(editor.isFocused(), "embedded text input should own focus before the navigation key");

        navigationOwner.fireEvent(keyEvent(KeyEvent.KEY_PRESSED, keyCode));

        assertTrue(editor.isFocused(), "container navigation should not steal focus from embedded text input");
        assertFalse(adjacentTarget.isFocused(), "adjacent action should not receive focus from text editing keys");
    }

    /// Creates a reusable virtualized list cell driven by an item updater.
    private static <T> M3ListCell<T> listCell(
            M3ListView<T> listView,
            BiConsumer<M3ListItem, T> itemUpdater
    ) {
        return new M3ListCell<>(listView) {
            /// Updates the retained row for the current data item.
            @Override
            protected void updateListItem(M3ListItem listItem, T item) {
                itemUpdater.accept(listItem, item);
            }
        };
    }

    /// Creates a reusable virtualized list cell with a caller-supplied retained row.
    private static <T> M3ListCell<T> listCell(M3ListView<T> listView, M3ListItem listItem) {
        return new M3ListCell<>(listView) {
            /// Creates the retained row owned by this cell.
            @Override
            protected M3ListItem createListItem() {
                return listItem;
            }
        };
    }

    /// Creates a key event for control behavior tests.
    private static KeyEvent keyEvent(EventType<KeyEvent> eventType, KeyCode code) {
        return keyEvent(eventType, code, false);
    }

    /// Creates a key event for control behavior tests with an optional Shift modifier.
    private static KeyEvent keyEvent(EventType<KeyEvent> eventType, KeyCode code, boolean shiftDown) {
        return keyEvent(eventType, code, shiftDown, false, false, false);
    }

    /// Creates a key event for control behavior tests with explicit keyboard modifiers.
    private static KeyEvent keyEvent(
            EventType<KeyEvent> eventType,
            KeyCode code,
            boolean shiftDown,
            boolean controlDown,
            boolean altDown,
            boolean metaDown
    ) {
        return new KeyEvent(eventType, "", "", code, shiftDown, controlDown, altDown, metaDown);
    }

    /// Creates a key event with an explicit source and target node.
    private static KeyEvent targetedKeyEvent(EventType<KeyEvent> eventType, KeyCode code, Node target) {
        return new KeyEvent(target, target, eventType, "", "", code, false, false, false, false);
    }

    /// Creates a typed key event for printable-key behavior tests.
    private static KeyEvent keyTypedEvent(String character) {
        return new KeyEvent(KeyEvent.KEY_TYPED, character, character, KeyCode.UNDEFINED, false, false, false, false);
    }

    /// Creates and installs a tooltip for tests that need installed tooltip behavior.
    private static M3Tooltip installTooltip(Node node, String text) {
        M3Tooltip tooltip = new M3Tooltip(text);
        M3Tooltip.install(node, tooltip);
        return tooltip;
    }

    /// Creates and installs a rich tooltip for tests that need installed tooltip behavior.
    private static M3RichTooltip installRichTooltip(
            Node node,
            String title,
            String supportingText,
            Node... actions
    ) {
        M3RichTooltip tooltip = richTooltip(title, supportingText, actions);
        M3Tooltip.install(node, tooltip);
        return tooltip;
    }
